// 层: 入口层 | 角色: 流程类（组装启动）
// main.cpp: 定义应用程序的入口点。
// 组装纯 C++ 核心层（相机池/队列/观察者）与 Qt UI 层：
//   UI 按钮 → CameraContext → CameraInterface → 虚拟相机；
//   采集线程 → 双缓冲队列 → QTimer（主线程取帧）→ 画面；
//   采集线程出错 → ListenerManager → ListenerBridge 信号 → 状态栏。
#include <QApplication>
#include <QColor>
#include <QCoreApplication>
#include <QFile>
#include <QMessageBox>
#include <QPalette>

#include <windows.h>

#include "agentfw/runtime/agent_host.h"
#include "config/parse_ui_json.h"
#include "core/camera_context.h"
#include "core/log.h"
#include "impl/camera_factory.h"
#include "observer/listener_manager.h"
#include "process/camera_image_queue.h"
#include "ui/listener_bridge.h"
#include "ui/main_window.h"

#include <iostream>
#include <memory>
#include <string>
#include <vector>

// 外观三件套：Fusion 风格 + 深色调色板 + QSS 样式表。
// 分工：QSS 管"能看到的"（按钮、面板、圆角），
//       调色板管 QSS 没覆盖的（滚动条、菜单、标准图标颜色）。
static void applyDarkTheme(QApplication& app) {
    app.setStyle("Fusion");  // 唯一能干净渲染深色的官方风格

    QPalette p;
    p.setColor(QPalette::Window, QColor(35, 38, 42));
    p.setColor(QPalette::WindowText, QColor(208, 212, 218));
    p.setColor(QPalette::Base, QColor(28, 30, 34));
    p.setColor(QPalette::AlternateBase, QColor(40, 43, 48));
    p.setColor(QPalette::Text, QColor(208, 212, 218));
    p.setColor(QPalette::Button, QColor(45, 49, 56));
    p.setColor(QPalette::ButtonText, QColor(208, 212, 218));
    p.setColor(QPalette::Highlight, QColor(42, 130, 228));
    p.setColor(QPalette::HighlightedText, QColor(255, 255, 255));
    app.setPalette(p);

    // 从资源编译进来的样式表（:/ 前缀 = 编译进 exe 的资源，与运行目录无关）
    QFile qss(":/ui/style.qss");
    if (qss.open(QFile::ReadOnly))
        app.setStyleSheet(QString::fromUtf8(qss.readAll()));
}

int main(int argc, char* argv[])
{
    QApplication app(argc, argv);
    applyDarkTheme(app);

    // 控制台代码页切 UTF-8：日志里的中文在 cmd/PowerShell 里才不乱码
    SetConsoleOutputCP(CP_UTF8);

    // 日志：exe 旁 logs/ 目录，文件 + 控制台双输出（文件打不开退化为仅控制台）
    camera::Log::init(QCoreApplication::applicationDirPath().toStdString() + "/logs");

    // 1. 枚举 + 创建 + 注入（启动链，纯 C++ 核心，与 UI 无关）
    // 参数面板 JSON 目录锚定 exe 旁，先告诉工厂再枚举（枚举时填进 DeviceInfo）
    camera::CameraFactory::setConfigDir(
        QCoreApplication::applicationDirPath().toStdString() + "/config");
    auto devices = camera::CameraFactory::enumerateDevices();
    // 边界校验：SDK 环境没准备好时给清晰提示，而不是往下走到空池抛异常崩溃
    if (devices.empty()) {
        camera::Log::error("未枚举到任何相机");
        QMessageBox::critical(nullptr, "camera",
            "未枚举到任何相机。\n请先运行 MVS 虚拟设备工具并保持运行：\n"
            "C:\\Program Files (x86)\\MVS\\Applications\\Win64\\VirtualDeviceTool.exe");
        return 1;
    }
    // 枚举明细由工厂内部记录（数据源头），这里不再重复
    std::vector<std::unique_ptr<camera::CameraInterface>> cameras;
    for (const auto& d : devices)
        cameras.push_back(camera::CameraFactory::createCamera(d.serialNumber));
    camera::CameraContext::initialize(std::move(cameras));
    camera::CameraContext& ctx = camera::CameraContext::instance();

    // CLI 模式：camera.exe --cli —— 控制台 REPL，无 GUI（调试 ReAct 循环最方便）
    if (argc > 1 && std::string(argv[1]) == "--cli") {
        const std::string settings =
            QCoreApplication::applicationDirPath().toStdString() + "/config/settings.json";
        const std::string knowledge =
            QCoreApplication::applicationDirPath().toStdString() + "/config/knowledge.json";
        const auto params =
            camera::ParseUiJson::parseFile(devices.front().configFile);
        camera::agentfw::AgentHost host(ctx, params, settings, knowledge);
        try {
            ctx.connectCamera();      // 工具操作需要设备已打开
            ctx.startAcquisition();
        } catch (const std::exception& e) {
            std::cout << "提示: 打开相机失败（" << e.what() << "），调参类工具将不可用\n";
        }
        std::cout << "AI 相机助手 CLI（输入 quit 退出）\n";
        for (;;) {
            std::cout << "> " << std::flush;
            std::string line;
            if (!std::getline(std::cin, line) || line == "quit")
                break;
            if (line.empty())
                continue;
            try {
                std::cout << host.runSync(line) << "\n\n";
            } catch (const std::exception& e) {
                std::cout << "错误: " << e.what() << "\n\n";
            }
        }
        camera::Log::info("CLI 模式退出");
        return 0;
    }

    // 2. 观察者 + 桥接：核心层事件 → Qt 信号
    camera::ListenerManager listenerMgr;
    camera::CameraImageQueue queue(2);
    ListenerBridge bridge;
    listenerMgr.registerListener(&bridge);

    // 3. 主窗口：图像显示 + 控制按钮（泵随窗口生灭）
    std::vector<std::string> serials;
    for (const auto& d : devices)
        serials.push_back(d.serialNumber);

    MainWindow win(ctx, queue, listenerMgr, bridge, std::move(serials));
    win.show();

    // 事件循环：Qt 从这里接管一切交互，直到窗口关闭
    const int rc = app.exec();
    camera::Log::info("程序退出");
    return rc;
}

