// 层: agentfw | 角色: 数据结构+静态加载（配置）
// agentfw/agent_config.cpp
#include "agentfw/agent_config.h"

#include "interface/camera_interface.h"

#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonParseError>

#include <cstdlib>

namespace camera::agentfw {

AgentConfig AgentConfig::load(const std::string& path) {
    AgentConfig cfg;

    QFile file(QString::fromStdString(path));
    if (!file.open(QIODevice::ReadOnly))
        throw CameraError(-1, "无法打开 AI 配置文件: " + path);

    QJsonParseError parseError;
    const QJsonDocument doc = QJsonDocument::fromJson(file.readAll(), &parseError);
    if (doc.isNull())
        throw CameraError(-1, "AI 配置 JSON 语法错误: " + parseError.errorString().toStdString());

    const QJsonObject root = doc.object();
    const QJsonObject env = root.value("env").toObject();

    cfg.apiKey = env.value("DEEPSEEK_API_KEY").toString().toStdString();
    const QString baseUrl = env.value("DEEPSEEK_BASE_URL").toString();
    cfg.baseUrl = baseUrl.isEmpty() ? cfg.baseUrl : baseUrl.toStdString();
    cfg.model = root.value("model").toString("deepseek-chat").toStdString();
    cfg.timeoutMs = root.value("timeoutMs").toInt(30000);
    cfg.maxRounds = root.value("maxRounds").toInt(8);
    cfg.mock = root.value("mock").toBool(false);
    cfg.systemPrompt = root.value("systemPrompt").toString().toStdString();

    // 真实环境变量优先（与 Claude Code 一致）
    if (const char* key = std::getenv("DEEPSEEK_API_KEY"); key && *key)
        cfg.apiKey = key;
    if (const char* url = std::getenv("DEEPSEEK_BASE_URL"); url && *url)
        cfg.baseUrl = url;

    return cfg;
}

} // namespace camera::agentfw

