// 层: agentfw | 角色: 数据结构（对话与工具类型）
// agentfw/chat_types.h
// 对话与工具调用的框架级类型：与任何厂商的线格式无关
// （OpenAI 兼容的转换在 DeepSeekLLMClient 内部完成）。
#pragma once

#include <string>
#include <vector>

namespace camera::agentfw {

enum class MessageRole { System, User, Assistant, Tool };

// 工具声明：给 AI 的"说明书"（也用于本地参数校验）
struct ToolDefinition {
    std::string name;
    std::string description;         // AI 靠它判断何时调用
    std::string parametersSchema;    // 简化 JSON schema：{"key":{"type":"string"},...}
};

// 一次工具调用请求（AI 发出，本地执行）
struct ToolCall {
    std::string id;         // 唯一 id：回喂 tool 消息时对应
    std::string name;       // 工具名
    std::string arguments;  // JSON 字符串
};

// 工具执行结果（本地执行后回喂 AI）
struct ToolResult {
    bool ok = false;
    std::string content;    // 成功：结果描述；失败：错误信息
};

struct ChatMessage {
    MessageRole role = MessageRole::User;
    std::string content;                // 文本内容（tool 消息 = 执行结果）
    std::vector<ToolCall> toolCalls;    // assistant 消息可能携带
    std::string toolCallId;             // tool 消息：对应哪次调用
};

struct ChatRequest {
    std::vector<ChatMessage> messages;
    std::vector<ToolDefinition> tools;  // 可用工具声明（每轮携带）
};

struct ChatResponse {
    std::string content;                // 最终答案（无工具调用时非空）
    std::vector<ToolCall> toolCalls;    // 工具调用请求（有则 content 为空）
};

} // namespace camera::agentfw

// 层: agentfw·实现层 | 角色: 实现类（OpenAI 兼容 LLM）
// agentfw/impl/deepseek_llm_client.cpp
#include "agentfw/impl/deepseek_llm_client.h"

#include "interface/camera_interface.h"

#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonValue>

#include <sstream>

namespace camera::agentfw {

DeepSeekLLMClient::DeepSeekLLMClient(IHttpClient& http, const AgentConfig& cfg)
    : http_(http), cfg_(cfg) {}

ChatResponse DeepSeekLLMClient::chat(const ChatRequest& request) {
    // ---- 框架类型 → OpenAI 兼容请求体 ----
    QJsonObject body;
    body["model"] = QString::fromStdString(cfg_.model);
    body["temperature"] = 0;

    QJsonArray messages;
    for (const ChatMessage& m : request.messages) {
        QJsonObject msg;
        switch (m.role) {
        case MessageRole::System:
            msg["role"] = "system";
            msg["content"] = QString::fromStdString(m.content);
            break;
        case MessageRole::User:
            msg["role"] = "user";
            msg["content"] = QString::fromStdString(m.content);
            break;
        case MessageRole::Assistant: {
            msg["role"] = "assistant";
            if (!m.toolCalls.empty()) {
                msg["content"] = QJsonValue::Null;
                QJsonArray calls;
                for (const ToolCall& tc : m.toolCalls) {
                    QJsonObject c;
                    c["id"] = QString::fromStdString(tc.id);
                    c["type"] = "function";
                    QJsonObject fn;
                    fn["name"] = QString::fromStdString(tc.name);
                    fn["arguments"] = QString::fromStdString(tc.arguments);
                    c["function"] = fn;
                    calls.append(c);
                }
                msg["tool_calls"] = calls;
            } else {
                msg["content"] = QString::fromStdString(m.content);
            }
            break;
        }
        case MessageRole::Tool:
            msg["role"] = "tool";
            msg["tool_call_id"] = QString::fromStdString(m.toolCallId);
            msg["content"] = QString::fromStdString(m.content);
            break;
        }
        messages.append(msg);
    }
    body["messages"] = messages;

    if (!request.tools.empty()) {
        QJsonArray tools;
        for (const ToolDefinition& def : request.tools) {
            QJsonObject t;
            t["type"] = "function";
            QJsonObject fn;
            fn["name"] = QString::fromStdString(def.name);
            fn["description"] = QString::fromStdString(def.description);
            const QJsonDocument schemaDoc =
                QJsonDocument::fromJson(QByteArray::fromStdString(def.parametersSchema));
            fn["parameters"] = schemaDoc.isNull() ? QJsonValue(QJsonObject())
                                                  : QJsonValue(schemaDoc.object());
            t["function"] = fn;
            tools.append(t);
        }
        body["tools"] = tools;
    }

    const std::string payload = QJsonDocument(body).toJson(QJsonDocument::Compact).toStdString();
    const std::string headers = "Content-Type: application/json\r\nAuthorization: Bearer "
        + cfg_.apiKey + "\r\n";
    const std::string response =
        http_.post(cfg_.baseUrl + "/chat/completions", headers, payload, cfg_.timeoutMs);

    // ---- OpenAI 兼容响应 → 框架类型 ----
    const QJsonDocument doc = QJsonDocument::fromJson(QByteArray::fromStdString(response));
    const QJsonArray choices = doc.object().value("choices").toArray();
    if (doc.isNull() || choices.isEmpty())
        throw CameraError(-1, "AI 响应不是预期的 JSON 格式");
    const QJsonObject message = choices[0].toObject().value("message").toObject();

    ChatResponse out;
    out.content = message.value("content").toString().toStdString();
    const QJsonArray toolCalls = message.value("tool_calls").toArray();
    for (const QJsonValue& v : toolCalls) {
        const QJsonObject c = v.toObject();
        const QJsonObject fn = c.value("function").toObject();
        ToolCall tc;
        tc.id = c.value("id").toString().toStdString();
        tc.name = fn.value("name").toString().toStdString();
        tc.arguments = fn.value("arguments").toString().toStdString();
        out.toolCalls.push_back(std::move(tc));
    }
    return out;
}

} // namespace camera::agentfw

