// 层: agentfw·实现层 | 角色: 实现类（内存知识库+RAG检索）
// agentfw/impl/in_memory_knowledge_store.cpp
#include "agentfw/impl/in_memory_knowledge_store.h"

#include "interface/camera_interface.h"

#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonParseError>

#include <algorithm>
#include <cctype>
#include <utility>

namespace camera::agentfw {

void InMemoryKnowledgeStore::load(const std::string& path) {
    QFile file(QString::fromStdString(path));
    if (!file.open(QIODevice::ReadOnly))
        throw CameraError(-1, "无法打开知识库文件: " + path);

    QJsonParseError parseError;
    const QJsonDocument doc = QJsonDocument::fromJson(file.readAll(), &parseError);
    if (doc.isNull() || !doc.isArray())
        throw CameraError(-1, "知识库 JSON 格式错误（应为数组）: "
                          + parseError.errorString().toStdString());

    entries_.clear();
    for (const QJsonValue& v : doc.array()) {
        const QJsonObject o = v.toObject();
        entries_.push_back({o.value("title").toString().toStdString(),
                            o.value("content").toString().toStdString()});
    }
}

std::vector<std::string> InMemoryKnowledgeStore::search(const std::string& query, size_t topK) {
    if (entries_.empty())
        return {};

    // 简单打分：query 中的连续中文字段/英文单词，在 title+content 中出现一次 +1
    std::vector<std::pair<size_t, int>> scores;  // (索引, 分数)
    for (size_t i = 0; i < entries_.size(); ++i) {
        const std::string text = entries_[i].title + " " + entries_[i].content;
        int score = 0;
        for (size_t pos = 0; pos < query.size();) {
            if (static_cast<unsigned char>(query[pos]) >= 0x80) {
                // 中文字段：取连续的非 ASCII 字符
                size_t end = pos;
                while (end < query.size() && static_cast<unsigned char>(query[end]) >= 0x80)
                    ++end;
                const std::string term = query.substr(pos, end - pos);
                if (!term.empty() && text.find(term) != std::string::npos)
                    ++score;
                pos = end;
            } else if (std::isalnum(static_cast<unsigned char>(query[pos]))) {
                size_t end = pos;
                while (end < query.size() && std::isalnum(static_cast<unsigned char>(query[end])))
                    ++end;
                const std::string term = query.substr(pos, end - pos);
                if (!term.empty() && text.find(term) != std::string::npos)
                    ++score;
                pos = end;
            } else {
                ++pos;
            }
        }
        if (score > 0)
            scores.push_back({i, score});
    }

    std::sort(scores.begin(), scores.end(),
              [](const auto& a, const auto& b) { return a.second > b.second; });

    std::vector<std::string> out;
    for (size_t k = 0; k < scores.size() && k < topK; ++k) {
        const Entry& e = entries_[scores[k].first];
        out.push_back("【" + e.title + "】" + e.content);
    }
    return out;
}

} // namespace camera::agentfw

// 层: agentfw·实现层 | 角色: 实现类（内存知识库+RAG检索）
// agentfw/impl/in_memory_knowledge_store.h
// 第4层：IKnowledgeStore 的内存实现。启动时加载 config/knowledge.json
// （[{title, content}] 数组），检索用关键词打分取 top-K。
#pragma once

#include "agentfw/interfaces/i_knowledge_store.h"

#include <string>
#include <vector>

namespace camera::agentfw {

class InMemoryKnowledgeStore : public IKnowledgeStore {
public:
    // 加载知识文件；失败抛 CameraError
    void load(const std::string& path);

    std::vector<std::string> search(const std::string& query, size_t topK) override;

private:
    struct Entry {
        std::string title;
        std::string content;
    };
    std::vector<Entry> entries_;
};

} // namespace camera::agentfw

