ChatResponse MockLLMClient::chat(const ChatRequest& request) {
    ++callCount_;
    ChatResponse out;
    if (callCount_ == 1) {
        // 第一轮：无论用户问什么，都"调用" set_param（演示工具调用链路）
        ToolCall call;
        call.id = "mock_call_1";
        call.name = "set_param";
        call.arguments = R"({"key":"ExposureTime","value":3000})";
        out.toolCalls.push_back(std::move(call));
        return out;
    }
    // 第二轮（收到工具结果回喂后）：给最终答案
    out.content = "已完成（Mock 演示）：曝光时间调整为 3000μs。这是写死的假回答，"
                  "用于不花 API 钱验证 ReAct 循环与工具调用全链路。";
    return out;
}

} // namespace camera::agentfw

