// 层: agentfw·实现层 | 角色: 实现类（WinHTTP 传输）
// agentfw/impl/winhttp_client.cpp
#include "agentfw/impl/winhttp_client.h"

#include "interface/camera_interface.h"

#include <windows.h>
#include <winhttp.h>

#include <sstream>
#include <string>
#include <vector>

namespace camera::agentfw {

namespace {

std::wstring toWide(const std::string& s) {
    return std::wstring(s.begin(), s.end());
}

// URL 形如 "https://host[:port]/path..."；拆出 host、port、路径
void splitUrl(const std::string& url, std::wstring& host, INTERNET_PORT& port, std::wstring& path) {
    std::string rest = url;
    if (rest.rfind("https://", 0) == 0) {
        rest = rest.substr(8);
        port = INTERNET_DEFAULT_HTTPS_PORT;
    } else if (rest.rfind("http://", 0) == 0) {
        rest = rest.substr(7);
        port = INTERNET_DEFAULT_HTTP_PORT;
    } else {
        throw CameraError(-1, "不支持的 URL 协议: " + url);
    }
    const auto slash = rest.find('/');
    const std::string hostPart = (slash == std::string::npos) ? rest : rest.substr(0, slash);
    path = toWide((slash == std::string::npos) ? "/" : rest.substr(slash));
    host = toWide(hostPart);
}

} // namespace

std::string WinHttpClient::post(const std::string& url, const std::string& headers,
                                const std::string& body, int timeoutMs) {
    std::wstring host, path;
    INTERNET_PORT port = INTERNET_DEFAULT_HTTPS_PORT;
    splitUrl(url, host, port, path);

    HINTERNET session = nullptr;
    HINTERNET connect = nullptr;
    HINTERNET request = nullptr;
    const auto fail = [&](const std::string& msg) -> std::string {
        if (request) WinHttpCloseHandle(request);
        if (connect) WinHttpCloseHandle(connect);
        if (session) WinHttpCloseHandle(session);
        throw CameraError(-1, msg);
    };

    session = WinHttpOpen(L"CameraAgentFW/1.0", WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,
                          WINHTTP_NO_PROXY_NAME, WINHTTP_NO_PROXY_BYPASS, 0);
    if (!session)
        return fail("WinHttpOpen 失败");

    connect = WinHttpConnect(session, host.c_str(), port, 0);
    if (!connect)
        return fail("WinHttpConnect 失败: " + std::string("无法连接 ") + std::string(host.begin(), host.end()));

    request = WinHttpOpenRequest(connect, L"POST", path.c_str(), nullptr,
                                 WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
                                 port == INTERNET_DEFAULT_HTTPS_PORT ? WINHTTP_FLAG_SECURE : 0);
    if (!request)
        return fail("WinHttpOpenRequest 失败");

    WinHttpSetTimeouts(request, timeoutMs, timeoutMs, timeoutMs, timeoutMs);

    const std::wstring wHeaders = toWide(headers);
    if (!WinHttpSendRequest(request, wHeaders.c_str(), static_cast<DWORD>(wHeaders.size()),
                            const_cast<char*>(body.data()), static_cast<DWORD>(body.size()),
                            static_cast<DWORD>(body.size()), 0))
        return fail("发送请求失败");

    if (!WinHttpReceiveResponse(request, nullptr))
        return fail("接收响应失败");

    DWORD status = 0;
    DWORD statusSize = sizeof(status);
    WinHttpQueryHeaders(request, WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
                        WINHTTP_HEADER_NAME_BY_INDEX, &status, &statusSize,
                        WINHTTP_NO_HEADER_INDEX);
    if (status < 200 || status >= 300) {
        std::ostringstream oss;
        oss << "HTTP " << status;
        return fail(oss.str());
    }

    std::string response;
    for (;;) {
        DWORD avail = 0;
        if (!WinHttpQueryDataAvailable(request, &avail) || avail == 0)
            break;
        std::vector<char> buf(avail);
        DWORD read = 0;
        if (!WinHttpReadData(request, buf.data(), avail, &read))
            break;
        response.append(buf.data(), read);
    }
    WinHttpCloseHandle(request);
    WinHttpCloseHandle(connect);
    WinHttpCloseHandle(session);
    return response;
}

} // namespace camera::agentfw

