namespace camera::agentfw {

AgentHost::AgentHost(CameraContext& ctx, const std::vector<ParamInfo>& params,
                     const std::string& settingsPath, const std::string& knowledgePath)
    : ctx_(ctx), params_(params), cfg_(AgentConfig::load(settingsPath)) {
    // 知识库（RAG 数据源）
    knowledge_.load(knowledgePath);
    Log::info("知识库加载完成: " + knowledgePath);

    // LLM 实现选型：mock 演示 or 真实 API
    if (cfg_.mock) {
        llm_ = std::make_unique<MockLLMClient>();
        Log::info("AI 客户端: Mock（演示模式，不发起真实请求）");
    } else {
        llm_ = std::make_unique<DeepSeekLLMClient>(http_, cfg_);
        Log::info("AI 客户端: DeepSeek (" + cfg_.baseUrl + ", " + cfg_.model + ")");
    }

    // 工具注册（业务桥：CameraContext → AI 可调用能力）
    registerCameraTools(registry_, ctx_, params_);
    Log::info("已注册工具: set_param / start_acquisition / stop_acquisition / switch_camera");

    // 运行时最后装配（依赖 llm_/registry_/knowledge_ 全部就绪）
    runtime_ = std::make_unique<AgentRuntime>(*llm_, registry_, knowledge_, cfg_);
}

AgentHost::~AgentHost() {
    if (worker_.joinable())
        worker_.join();
}

void AgentHost::startAsync(const std::string& userInput, DoneFn done, ProgressFn progress) {
    if (busy_.exchange(true))
        return;  // 已有请求在途
    if (worker_.joinable())
        worker_.join();
    worker_ = std::thread([this, userInput, done = std::move(done), progress = std::move(progress)] {
        try {
            const std::string result = runtime_->run(userInput, progress);
            if (done)
                done(true, result);
        } catch (const std::exception& e) {
            Log::error(std::string("AI 请求失败: ") + e.what());
            if (done)
                done(false, e.what());
        }
        busy_ = false;
    });
}

std::string AgentHost::runSync(const std::string& userInput) {
    busy_ = true;
    try {
        const std::string result = runtime_->run(userInput);
        busy_ = false;
        return result;
    } catch (...) {
        busy_ = false;
        throw;
    }
}

void AgentHost::clearHistory() {
    runtime_->clearHistory();
}

} // namespace camera::agentfw

