// 层: agentfw·应用层 | 角色: 流程类（ReAct 循环引擎）
// agentfw/runtime/agent_runtime.cpp
#include "agentfw/runtime/agent_runtime.h"

#include "core/log.h"
#include "interface/camera_interface.h"

#include <sstream>
#include <utility>

namespace camera::agentfw {

AgentRuntime::AgentRuntime(ILLMClient& llm, IToolInvoker& tools, IKnowledgeStore& knowledge,
                           const AgentConfig& cfg)
    : llm_(llm), tools_(tools), knowledge_(knowledge), cfg_(cfg) {}

std::string AgentRuntime::run(const std::string& userInput, const ProgressFn& onProgress) {
    history_.push_back({MessageRole::User, userInput, {}, {}});

    // RAG：检索相关知识拼进 system 消息（每轮提问都检索，内容更贴合当前问题）
    std::ostringstream system;
    system << cfg_.systemPrompt;
    const auto snippets = knowledge_.search(userInput, 2);
    if (!snippets.empty()) {
        system << "\n\n相关知识：\n";
        for (const auto& s : snippets)
            system << "- " << s << "\n";
    }
    const std::string systemText = system.str();

    for (int round = 0; round < cfg_.maxRounds; ++round) {
        // 每轮都发全量历史（LLM 无状态）
        ChatRequest request;
        request.messages.push_back({MessageRole::System, systemText, {}, {}});
        request.messages.insert(request.messages.end(), history_.begin(), history_.end());
        request.tools = tools_.definitions();

        const ChatResponse response = llm_.chat(request);

        if (response.toolCalls.empty())
            return response.content.empty() ? "（AI 没有返回内容）" : response.content;

        // assistant 消息（带工具调用）入历史
        history_.push_back({MessageRole::Assistant, "", response.toolCalls, {}});

        // 逐个执行工具，结果回喂
        for (const ToolCall& call : response.toolCalls) {
            Log::info("AI 调用工具: " + call.name + " 参数 " + call.arguments);
            const ToolResult result = tools_.invoke(call);
            Log::info(std::string("工具 ") + call.name + (result.ok ? " 成功: " : " 失败: ")
                      + result.content);
            if (onProgress)
                onProgress(call, result);
            history_.push_back({MessageRole::Tool, result.content, {}, call.id});
        }
    }
    throw CameraError(-1, "ReAct 循环达到最大轮数（" + std::to_string(cfg_.maxRounds) + "）仍未完成");
}

void AgentRuntime::clearHistory() {
    history_.clear();
}

} // namespace camera::agentfw

