// 层: agentfw·应用层 | 角色: 管理类（工具注册表：白名单+校验+分发）
// agentfw/runtime/tool_registry.cpp
#include "agentfw/runtime/tool_registry.h"

#include "interface/camera_interface.h"

#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonValue>

namespace camera::agentfw {

void ToolRegistry::registerTool(const ToolDefinition& def, ToolFn fn) {
    std::unique_lock lock(mtx_);
    defs_[def.name] = def;
    fns_[def.name] = std::move(fn);
}

ToolResult ToolRegistry::invoke(const ToolCall& call) {
    ToolFn fn;
    ToolDefinition def;
    {
        // 读锁只做查表，查到就拷出来，锁外执行
        std::shared_lock lock(mtx_);
        const auto itDef = defs_.find(call.name);
        const auto itFn = fns_.find(call.name);
        if (itDef == defs_.end() || itFn == fns_.end())
            return {false, "未知工具: " + call.name + "（AI 只能调用已注册的工具）"};
        def = itDef->second;
        fn = itFn->second;
    }
    try {
        validateArgs(def.parametersSchema, call.arguments);
        return fn(call.arguments);
    } catch (const std::exception& e) {
        return {false, "参数校验失败: " + std::string(e.what())};
    }
}

std::vector<ToolDefinition> ToolRegistry::definitions() const {
    std::shared_lock lock(mtx_);
    std::vector<ToolDefinition> out;
    out.reserve(defs_.size());
    for (const auto& [name, def] : defs_)
        out.push_back(def);
    return out;
}

void ToolRegistry::validateArgs(const std::string& schemaJson, const std::string& argsJson) {
    const QJsonDocument schemaDoc = QJsonDocument::fromJson(QByteArray::fromStdString(schemaJson));
    const QJsonDocument argsDoc = QJsonDocument::fromJson(QByteArray::fromStdString(argsJson));
    if (schemaDoc.isNull() || argsDoc.isNull() || !argsDoc.isObject())
        throw CameraError(-1, "参数不是合法 JSON 对象");
    const QJsonObject schema = schemaDoc.object();
    const QJsonObject args = argsDoc.object();

    for (auto it = schema.begin(); it != schema.end(); ++it) {
        const QString key = it.key();
        const QJsonObject spec = it.value().toObject();
        const QString type = spec.value("type").toString();
        const bool required = spec.value("required").toBool(type.isEmpty() ? false : true);

        if (!args.contains(key)) {
            if (required)
                throw CameraError(-1, ("缺少必填参数: " + key).toStdString());
            continue;
        }
        const QJsonValue v = args.value(key);
        bool ok = false;
        if (type == "string") ok = v.isString();
        else if (type == "number") ok = v.isDouble();
        else if (type == "bool") ok = v.isBool();
        else if (type.isEmpty()) ok = true;  // 类型不限
        if (!ok)
            throw CameraError(-1, ("参数 " + key + " 类型错误，应为 " + type).toStdString());
    }
}

} // namespace camera::agentfw

