// 层: agentfw·应用层 | 角色: 管理类（工具注册表：白名单+校验+分发）
// agentfw/runtime/tool_registry.h
// 第2层：工具注册表 = AI 能力的白名单 + 安检门 + 传菜口。
// 线程安全：shared_mutex——注册（写）低频拿唯一锁，调用（读）拿共享锁；
// Call 查到函数后拷贝参数、释放锁再执行，避免长时间持锁。
#pragma once

#include "agentfw/chat_types.h"
#include "agentfw/interfaces/i_tool_invoker.h"

#include <functional>
#include <map>
#include <shared_mutex>

namespace camera::agentfw {

class ToolRegistry : public IToolInvoker {
public:
    // 工具函数：收 arguments（JSON 字符串），返回结果
    using ToolFn = std::function<ToolResult(const std::string& argumentsJson)>;

    void registerTool(const ToolDefinition& def, ToolFn fn);

    ToolResult invoke(const ToolCall& call) override;
    std::vector<ToolDefinition> definitions() const override;

private:
    // 简化 schema 校验：必填 + 类型（string/number/bool）；通过则原样返回参数，否则抛 CameraError
    static void validateArgs(const std::string& schemaJson, const std::string& argsJson);

    mutable std::shared_mutex mtx_;
    std::map<std::string, ToolDefinition> defs_;
    std::map<std::string, ToolFn> fns_;
};

} // namespace camera::agentfw

