// 层: agentfw·应用层 | 角色: 业务桥（CameraContext→AI 工具）
// agentfw/tools/camera_tools.cpp
#include "agentfw/tools/camera_tools.h"

#include "interface/camera_interface.h"

#include <QJsonDocument>
#include <QJsonObject>

#include <cstdlib>
#include <sstream>

namespace camera::agentfw {

namespace {

std::string formatDouble(double v) {
    std::ostringstream oss;
    oss << v;
    return oss.str();
}

const ParamInfo* findParam(const std::vector<ParamInfo>& params, const std::string& key) {
    for (const auto& p : params) {
        if (p.key == key)
            return &p;
    }
    return nullptr;
}

} // namespace

void registerCameraTools(ToolRegistry& registry, CameraContext& ctx,
                         const std::vector<ParamInfo>& params) {
    // ---- set_param：调参（带范围 clamp + enum 校验——AI 输出不可信）----
    registry.registerTool(
        {"set_param",
         "修改相机参数。key 必须是参数表里的参数名（如 ExposureTime），value 为数值或字符串",
         R"({"key":{"type":"string"},"value":{}})"},
        [&ctx, &params](const std::string& argsJson) -> ToolResult {
            const QJsonDocument doc = QJsonDocument::fromJson(QByteArray::fromStdString(argsJson));
            if (doc.isNull())
                return {false, "参数不是合法 JSON"};
            const QJsonObject args = doc.object();
            const std::string key = args.value("key").toString().toStdString();
            const ParamInfo* p = findParam(params, key);
            if (!p)
                return {false, "未知参数: " + key + "（不在参数表中）"};

            const QJsonValue v = args.value("value");
            std::string newValue;
            try {
                if (p->type == "int") {
                    if (!v.isDouble())
                        return {false, key + " 需要数值"};
                    double val = v.toDouble();
                    if (val < p->min) val = p->min;
                    if (val > p->max) val = p->max;
                    const int64_t iv = static_cast<int64_t>(val);
                    const int64_t old = ctx.getParamInt(key);
                    if (iv == old)
                        return {true, key + " 已经是 " + std::to_string(iv) + "，无需修改"};
                    ctx.setParam(key, iv);
                    newValue = std::to_string(iv);
                    return {true, "成功：" + key + " " + std::to_string(old) + " → " + newValue};
                }
                if (p->type == "float") {
                    if (!v.isDouble())
                        return {false, key + " 需要数值"};
                    double val = v.toDouble();
                    if (val < p->min) val = p->min;
                    if (val > p->max) val = p->max;
                    const double old = ctx.getParamFloat(key);
                    if (val == old)
                        return {true, key + " 已经是 " + formatDouble(val) + "，无需修改"};
                    ctx.setParam(key, val);
                    return {true, "成功：" + key + " " + formatDouble(old) + " → "
                            + formatDouble(val)};
                }
                if (p->type == "bool") {
                    if (!v.isBool())
                        return {false, key + " 需要 true/false"};
                    const int64_t bv = v.toBool() ? 1 : 0;
                    const int64_t old = ctx.getParamInt(key);
                    if (bv == old)
                        return {true, key + " 无需修改"};
                    ctx.setParam(key, bv);
                    return {true, "成功：" + key + " → " + (bv ? "true" : "false")};
                }
                if (p->type == "enum") {
                    if (!v.isString())
                        return {false, key + " 需要字符串（可选: " + [&] {
                            std::string s;
                            for (size_t i = 0; i < p->options.size(); ++i) {
                                if (i) s += "/";
                                s += p->options[i];
                            }
                            return s;
                        }() + "）"};
                    const std::string sv = v.toString().toStdString();
                    bool valid = false;
                    for (const auto& opt : p->options)
                        if (opt == sv) { valid = true; break; }
                    if (!valid)
                        return {false, sv + " 不是合法选项"};
                    const std::string old = ctx.getParamString(key);
                    if (sv == old)
                        return {true, key + " 已经是 " + sv + "，无需修改"};
                    ctx.setParam(key, sv);
                    return {true, "成功：" + key + " " + old + " → " + sv};
                }
                // string
                if (!v.isString())
                    return {false, key + " 需要字符串"};
                const std::string sv = v.toString().toStdString();
                const std::string old = ctx.getParamString(key);
                if (sv == old)
                    return {true, key + " 无需修改"};
                ctx.setParam(key, sv);
                return {true, "成功：" + key + " " + old + " → " + sv};
            } catch (const std::exception& e) {
                return {false, std::string(e.what())};
            }
        });

    // ---- 采集控制 ----
    registry.registerTool(
        {"start_acquisition", "开始图像采集（相机开始出帧）", R"({})"},
        [&ctx](const std::string&) -> ToolResult {
            try {
                ctx.startAcquisition();
                return {true, "采集已开始"};
            } catch (const std::exception& e) {
                return {false, e.what()};
            }
        });

    registry.registerTool(
        {"stop_acquisition", "停止图像采集", R"({})"},
        [&ctx](const std::string&) -> ToolResult {
            try {
                ctx.stopAcquisition();
                return {true, "采集已停止"};
            } catch (const std::exception& e) {
                return {false, e.what()};
            }
        });

    // ---- 切换相机 ----
    registry.registerTool(
        {"switch_camera", "按序列号切换到另一台相机", R"({"serial":{"type":"string"}})"},
        [&ctx](const std::string& argsJson) -> ToolResult {
            const QJsonDocument doc = QJsonDocument::fromJson(QByteArray::fromStdString(argsJson));
            if (doc.isNull())
                return {false, "参数不是合法 JSON"};
            const std::string serial =
                doc.object().value("serial").toString().toStdString();
            if (serial.empty())
                return {false, "缺少序列号 serial"};
            try {
                ctx.switchCamera(serial);
                return {true, "已切换到 " + serial};
            } catch (const std::exception& e) {
                return {false, e.what()};
            }
        });
}

} // namespace camera::agentfw

