    std::string key;            // 参数键（setParam/getParam 用，和相机内部一致）
    std::string type;           // "int" | "float" | "enum" | "bool" | "string"
    double min = 0;             // 数值型下限
    double max = 0;             // 数值型上限
    double defaultValue = 0;    // 数值型默认值（bool 用 0/1）
    std::vector<std::string> options;  // enum 型选项列表
    std::string defaultString;  // enum/string 型默认值
