// 层: 配置层 | 角色: 静态方法类（JSON 解析器）
// config/parse_ui_json.cpp
// 用 Qt 的 QJsonDocument 解析：JSON 文本 → 结构化模型。
// 语法错误/字段缺失都报错返回，绝不静默产出残缺模型。
#include "config/parse_ui_json.h"

#include "interface/camera_interface.h"

#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonParseError>
#include <QJsonValue>

#include <utility>

namespace camera {

std::vector<ParamInfo> ParseUiJson::parseFile(const std::string& path) {
    QFile file(QString::fromStdString(path));
    if (!file.open(QIODevice::ReadOnly))
        throw CameraError(-1, "无法打开参数配置文件: " + path);

    QJsonParseError parseError;
    const QJsonDocument doc = QJsonDocument::fromJson(file.readAll(), &parseError);
    if (doc.isNull())
        throw CameraError(-1, "JSON 语法错误: " + parseError.errorString().toStdString());

    const QJsonArray params = doc.object().value("params").toArray();

    std::vector<ParamInfo> result;
    for (const QJsonValue& value : params) {
        const QJsonObject o = value.toObject();

        ParamInfo p;
        p.name = o.value("name").toString().toStdString();
        p.key = o.value("key").toString().toStdString();
        p.type = o.value("type").toString().toStdString();
        p.min = o.value("min").toDouble();
        p.max = o.value("max").toDouble();
        p.defaultValue = o.value("default").toDouble();
        p.unit = o.value("unit").toString().toStdString();
        p.group = o.value("group").toString().toStdString();
        for (const QJsonValue& opt : o.value("options").toArray())
            p.options.push_back(opt.toString().toStdString());

        // bool/enum/string 的默认值按字符串处理（enum 的 default 是选项名）
        if (p.type == "bool")
            p.defaultValue = o.value("default").toBool() ? 1 : 0;
        else if (p.type == "enum" || p.type == "string")
            p.defaultString = o.value("default").toString().toStdString();

        result.push_back(std::move(p));
    }
    return result;
}

} // namespace camera

