// 层: 核心层 | 角色: 管理类（单例：相机池所有权+转发）
// core/camera_context.cpp
// 相机上下文实现：目前是"所有权 + 方法转发"的最小形态。
// 后续观察者模式（状态广播）、采集线程、图像队列接入后，业务逻辑在这里生长。
#include "core/camera_context.h"

#include <utility>

namespace camera {

// 静态成员定义：全程序唯一的 CameraContext 实例（初始为空 = 未初始化）
std::unique_ptr<CameraContext> CameraContext::instance_;

// ---- 单例访问 ----
CameraContext& CameraContext::instance() {
    // 未初始化时抛异常，而不是悄悄返回 null/裸指针：调用方一定能看到问题
    if (!instance_)
        throw CameraError(-1, "CameraContext 未初始化，请先调用 initialize()");
    return *instance_;
}

void CameraContext::initialize(std::vector<std::unique_ptr<CameraInterface>> cameras) {
    // 只允许一次：单例的语义就是全局唯一，重复初始化多半是程序逻辑 bug
    if (instance_)
        throw CameraError(-1, "CameraContext 已初始化，不允许重复初始化");
    // 注意：不能用 std::make_unique —— 构造函数是私有的，
    // make_unique 内部调构造时访问权限在它自己那里检查，会报 C2248；
    // new 直接写在本成员函数内，才有权限访问私有构造函数。
    instance_ = std::unique_ptr<CameraContext>(new CameraContext(std::move(cameras)));
}

CameraContext::CameraContext(std::vector<std::unique_ptr<CameraInterface>> cameras)
    : cameras_(std::move(cameras)) {
    // 边界校验：拒绝空池，避免后续所有调用变成空指针解引用
    if (cameras_.empty())
        throw CameraError(-1, "相机池为空");
    active_ = cameras_.front().get();  // 默认使用池中的第一台相机
}

// ---------------------------------------------------------------------------
// 生命周期
// ---------------------------------------------------------------------------
void CameraContext::connectCamera() {
    active_->open();
}

void CameraContext::disconnectCamera() {
    active_->close();
}

bool CameraContext::isConnected() const {
    // 不重复保存一份"是否连接"的状态：相机的状态就是唯一真相
    return active_->isOpen();
}

// ---------------------------------------------------------------------------
// 采集控制
// ---------------------------------------------------------------------------
void CameraContext::startAcquisition() {
    active_->startGrabbing();
}

void CameraContext::stopAcquisition() {
    active_->stopGrabbing();
}

bool CameraContext::grabFrame(ImageData& out, uint32_t timeoutMs) {
    return active_->grabFrame(out, timeoutMs);
}

// ---------------------------------------------------------------------------
// 多相机：在相机池中切换当前采集的相机
// ---------------------------------------------------------------------------
void CameraContext::switchCamera(const std::string& serial) {
    // 按序列号在池中查找目标相机
    CameraInterface* target = nullptr;
    for (auto& c : cameras_) {
        if (c->deviceInfo().serialNumber == serial) {
            target = c.get();
            break;
        }
    }
    if (!target)
        throw CameraError(-1, "未找到序列号为 " + serial + " 的相机");

    if (target == active_)
        return;  // 已经在用这台相机，无需切换

    // 释放当前相机（若已打开）：先停采集再关闭。
    // stopGrabbing 在 Open / Grabbing 状态都安全（只有 Closed 会抛）。
    if (active_->isOpen()) {
        active_->stopGrabbing();
        active_->close();
    }

    // 打开并启动目标相机，接替采集
    target->open();
    target->startGrabbing();
    active_ = target;
}

// ---------------------------------------------------------------------------
// 参数读写
// ---------------------------------------------------------------------------
void CameraContext::setParam(const std::string& name, int64_t value) {
    active_->setParam(name, value);
}

void CameraContext::setParam(const std::string& name, double value) {
    active_->setParam(name, value);
}

void CameraContext::setParam(const std::string& name, const std::string& value) {
    active_->setParam(name, value);
}

int64_t CameraContext::getParamInt(const std::string& name) const {
    return active_->getParamInt(name);
}

double CameraContext::getParamFloat(const std::string& name) const {
    return active_->getParamFloat(name);
}

std::string CameraContext::getParamString(const std::string& name) const {
    return active_->getParamString(name);
}

// ---------------------------------------------------------------------------
// 设备信息
// ---------------------------------------------------------------------------
DeviceInfo CameraContext::deviceInfo() const {
    return active_->deviceInfo();
}

} // namespace camera

