// 层: 核心层 | 角色: 管理类（单例：相机池所有权+转发）
// core/camera_context.h
// 相机上下文（业务层）：统一管理相机，全程序唯一的业务枢纽（单例）。
// UI 层与采集线程只与它交互，不接触任何具体相机类。
// 设计要点：
//  1. 单例——整个程序只有一个 Context，UI 各面板通过 instance() 访问；
//  2. 保留依赖注入——相机池由外部创建后经 initialize() 注入（私有构造），
//     Context 只依赖 CameraInterface，将来接入 HikCamera 时本类零改动；
//  3. 相机池——Context 可持有多台相机，switchCamera() 切换当前采集的相机。
#pragma once

#include "interface/camera_interface.h"

#include <memory>
#include <string>
#include <vector>

namespace camera {

class CameraContext {
public:
    // ---- 单例访问 ----
    static CameraContext& instance();   // 获取唯一实例（未初始化则抛 CameraError）
    static void initialize(std::vector<std::unique_ptr<CameraInterface>> cameras);  // 全局初始化（注入相机池），只允许一次

    // 禁止拷贝：单例不允许出现第二个实例
    CameraContext(const CameraContext&) = delete;
    CameraContext& operator=(const CameraContext&) = delete;

    // ---- 生命周期（面向 UI 的语义化接口）----
    void connectCamera();      // 打开相机；失败抛 CameraError
    void disconnectCamera();   // 关闭相机
    bool isConnected() const;  // 是否已连接（直接查相机状态，单一数据源）

    // ---- 多相机 ----
    void switchCamera(const std::string& serial);  // 切换当前采集的相机（自动停/关旧机，开/采新机）

    // ---- 采集控制 ----
    void startAcquisition();
    void stopAcquisition();
    bool grabFrame(ImageData& out, uint32_t timeoutMs = 1000);

    // ---- 参数读写（转发给相机）----
    void setParam(const std::string& name, int64_t value);
    void setParam(const std::string& name, double value);
    void setParam(const std::string& name, const std::string& value);

    int64_t getParamInt(const std::string& name) const;
    double getParamFloat(const std::string& name) const;
    std::string getParamString(const std::string& name) const;

    // ---- 设备信息 ----
    DeviceInfo deviceInfo() const;

private:
    // 私有构造：外部不能直接 new，只能由 initialize() 创建唯一实例
    explicit CameraContext(std::vector<std::unique_ptr<CameraInterface>> cameras);

    static std::unique_ptr<CameraContext> instance_;  // 全局唯一实例

    std::vector<std::unique_ptr<CameraInterface>> cameras_;  // 相机池：所有权在这里
    CameraInterface* active_ = nullptr;  // 当前采集的相机（借用指针：只引用，不拥有）
};

} // namespace camera

