// 层: 核心层 | 角色: 静态方法类（横切关注点：日志封装）
// core/log.cpp
#include "core/log.h"

// header-only 模式：只在本文本单元定义，其他文件 include log.h 不碰 spdlog
#define SPDLOG_HEADER_ONLY
#include <spdlog/sinks/rotating_file_sink.h>
#include <spdlog/sinks/stdout_color_sinks.h>
#include <spdlog/spdlog.h>

#include <ctime>
#include <filesystem>
#include <fstream>
#include <memory>
#include <sstream>

namespace camera {

namespace {
std::shared_ptr<spdlog::logger> g_logger;
}

void Log::init(const std::string& logDir) {
    // 日期文件名：camera_2026-09-04.log，按 5MB x 3 滚动，防止日志无限膨胀
    std::time_t t = std::time(nullptr);
    std::tm tm{};
    localtime_s(&tm, &t);
    std::ostringstream name;
    name << logDir << "/camera_" << (tm.tm_year + 1900) << "-"
         << (tm.tm_mon + 1 < 10 ? "0" : "") << (tm.tm_mon + 1) << "-"
         << (tm.tm_mday < 10 ? "0" : "") << tm.tm_mday << ".log";

    auto consoleSink = std::make_shared<spdlog::sinks::stdout_color_sink_mt>();
    std::vector<spdlog::sink_ptr> sinks{consoleSink};
    try {
        std::filesystem::create_directories(logDir);
        // UTF-8 BOM：Windows 记事本靠 BOM 识别 UTF-8，中文日志没有它打开会乱码。
        // 只在文件为空时写一次；spdlog 以追加模式打开，BOM 会留在文件头。
        // （滚动切出的新文件没有 BOM，用 VS Code/Notepad++ 等工具打开不受影响）
        {
            std::ifstream check(name.str(), std::ios::binary);
            const bool empty = check.peek() == std::ifstream::traits_type::eof();
            check.close();
            if (empty) {
                std::ofstream out(name.str(), std::ios::binary | std::ios::app);
                out.write("\xEF\xBB\xBF", 3);
            }
        }
        auto fileSink =
            std::make_shared<spdlog::sinks::rotating_file_sink_mt>(name.str(), 5 * 1024 * 1024, 3);
        sinks.push_back(fileSink);
    } catch (const std::exception& e) {
        // 日志系统绝不能把主程序带崩：文件打不开就退化为仅控制台
        consoleSink->set_level(spdlog::level::err);
    }

    g_logger = std::make_shared<spdlog::logger>("camera", sinks.begin(), sinks.end());
    g_logger->set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%l] %v");
    g_logger->set_level(spdlog::level::info);
    g_logger->flush_on(spdlog::level::info);  // 每条都立即落盘：日志必须即时，不留缓冲
}

void Log::ensure() {
    if (g_logger)
        return;
    auto consoleSink = std::make_shared<spdlog::sinks::stdout_color_sink_mt>();
    g_logger = std::make_shared<spdlog::logger>("camera", consoleSink);
    g_logger->set_pattern("[%Y-%m-%d %H:%M:%S.%e] [%l] %v");
    g_logger->set_level(spdlog::level::info);
}

void Log::info(const std::string& msg) {
    ensure();
    g_logger->info(msg);
}

void Log::warn(const std::string& msg) {
    ensure();
    g_logger->warn(msg);
}

void Log::error(const std::string& msg) {
    ensure();
    g_logger->error(msg);
}

} // namespace camera

