// 层: 实现层 | 角色: 静态方法类（工厂：枚举+创建）
// impl/camera_factory.cpp
// 工厂实现：枚举/创建两条产线。
//   HAVE_MVS（CMake 探测到 MVS SDK 时定义）→ 调海康 SDK 枚举设备，创建 HikCamera；
//   否则回退模拟设备表（VSN- 前缀），保证没有 SDK 的机器也能跑起来开发 UI。
#include "camera_factory.h"
#include "core/log.h"
#include "impl/virtual/virtual_camera.h"

#ifdef HAVE_MVS
#include "impl/hik/hik_camera.h"

#include <map>
#include <utility>
#endif

namespace camera {

    namespace {

// 参数 JSON 目录：main.cpp 启动时锚定到 exe 旁的 config/
std::string gConfigDir = "config";

#ifdef HAVE_MVS
// 枚举缓存：createCamera 按序列号取回设备信息（CreateHandle 要用枚举时的结构）
std::map<std::string, MV_CC_DEVICE_INFO> gMvsDevicesBySerial;

// SDK 进程级初始化：第一次用到时执行，进程退出时自动反初始化（RAII）。
// MV_CC_Initialize 只需调用一次，静态局部变量保证这一点。
class MvsSdk {
public:
    MvsSdk() : initRc_(MV_CC_Initialize()) {}
    ~MvsSdk() { MV_CC_Finalize(); }

private:
    int initRc_;
};

MvsSdk& mvsSdk() {
    static MvsSdk sdk;
    return sdk;
}
#endif

} // namespace

void CameraFactory::setConfigDir(const std::string& dir) {
    gConfigDir = dir;
}

std::vector<DeviceInfo> CameraFactory::enumerateDevices() {
#ifdef HAVE_MVS
    mvsSdk();  // 触发 SDK 进程级初始化
    gMvsDevicesBySerial.clear();

    MV_CC_DEVICE_INFO_LIST list{};
    // 掩码含虚拟设备类型：MVS 虚拟相机上报 MV_VIR_GIGE_DEVICE（0x10），
    // 只填 GigE|USB 会被 SDK 过滤掉，枚举结果恒为 0
    const int rc = MV_CC_EnumDevices(MV_GIGE_DEVICE | MV_USB_DEVICE
                                     | MV_VIR_GIGE_DEVICE | MV_VIR_USB_DEVICE, &list);
    if (rc != MV_OK)
        throw CameraError(rc, "MVS 枚举设备失败（MVS 客户端里能看到虚拟相机吗？）");

    std::vector<DeviceInfo> devices;
    for (unsigned int i = 0; i < list.nDeviceNum; ++i) {
        const MV_CC_DEVICE_INFO& dev = *list.pDeviceInfo[i];
        DeviceInfo d;
        // 设备信息字段在 union 里，随传输层类型不同。虚拟相机具体是哪种
        // 传输层装好 MVS 后实测确认——两种都处理了，这里不会漏。
        // （如需"只列出虚拟相机"，在这里按型号/传输层加过滤即可）
        // 虚拟 GigE/USB 与真实设备共用同一套信息结构（虚拟相机模拟的就是它们）
        if (dev.nTLayerType == MV_GIGE_DEVICE || dev.nTLayerType == MV_VIR_GIGE_DEVICE) {
            const auto& g = dev.SpecialInfo.stGigEInfo;
            d.vendor = reinterpret_cast<const char*>(g.chManufacturerName);
            d.modelName = reinterpret_cast<const char*>(g.chModelName);
            d.serialNumber = reinterpret_cast<const char*>(g.chSerialNumber);
        } else if (dev.nTLayerType == MV_USB_DEVICE || dev.nTLayerType == MV_VIR_USB_DEVICE) {
            const auto& u = dev.SpecialInfo.stUsb3VInfo;
            d.vendor = reinterpret_cast<const char*>(u.chManufacturerName);
            d.modelName = reinterpret_cast<const char*>(u.chModelName);
            d.serialNumber = reinterpret_cast<const char*>(u.chSerialNumber);
        } else {
            continue;  // 其他传输层（1394/CameraLink/采集卡 GenTL）不在本次范围
        }
        d.configFile = gConfigDir + "/hik_virtual_camera.json";
        gMvsDevicesBySerial[d.serialNumber] = dev;
        devices.push_back(std::move(d));
    }
    Log::info("MVS 枚举到 " + std::to_string(devices.size()) + " 台设备");
    for (const auto& d : devices)
        Log::info("设备: " + d.vendor + " " + d.modelName + " (" + d.serialNumber + ")");
    return devices;
#else
    // 无 SDK 环境：模拟"机器上插了两台虚拟相机"，UI/业务层开发调试照常
    Log::info("无 MVS SDK：回退 2 台模拟设备");
    Log::info("设备: Virtual VirtualCamera (VSN-0001)");
    Log::info("设备: Virtual VirtualCamera (VSN-0002)");
    return {
        {"Virtual", "VirtualCamera", "VSN-0001", gConfigDir + "/virtual_camera.json"},
        {"Virtual", "VirtualCamera", "VSN-0002", gConfigDir + "/virtual_camera.json"},
    };
#endif
}

std::unique_ptr<CameraInterface> CameraFactory::createCamera(const std::string& serial) {
#ifdef HAVE_MVS
    // 海康分支：序列号命中枚举缓存 → 创建 HikCamera
    const auto it = gMvsDevicesBySerial.find(serial);
    if (it != gMvsDevicesBySerial.end())
        return std::make_unique<HikCamera>(serial, it->second,
                                           gConfigDir + "/hik_virtual_camera.json");
#endif
    if (serial.rfind("VSN-", 0) == 0)  // 虚拟相机序列号前缀（无 MVS 时的回退路径）
        return std::make_unique<VirtualCamera>(serial);
    throw CameraError(-1, "无法为序列号创建相机（未知厂商）: " + serial);
}

} // namespace camera

