// 层: 实现层 | 角色: 实现类（海康 MVS SDK 适配）
// impl/hik/hik_camera.cpp
// 海康相机实现：CameraInterface 的方法族 → MVS SDK C API。
#include "hik_camera.h"

#include "config/parse_ui_json.h"
#include "core/.h"

#include <iomanip>
#include <sstream>
#include <utility>
#include <vector>

namespace camera {

HikCamera::HikCamera(std::string serial, MV_CC_DEVICE_INFO devInfo, std::string configFile)
    : devInfo_(devInfo) {
    // 参数类型路由表：同一个 JSON 既驱动 UI 面板，也告诉本类每个 key
    // 该走哪个 SDK 调用（bool 走 SetBoolValue、enum 走 SetEnumValueByString……）
    for (const ParamInfo& p : ParseUiJson::parseFile(configFile))
        paramTypes_[p.key] = p.type;

    // 设备信息字段在 union 里，随传输层类型不同，按类型取
    info_.serialNumber = std::move(serial);
    info_.configFile = std::move(configFile);
    if (devInfo_.nTLayerType == MV_GIGE_DEVICE || devInfo_.nTLayerType == MV_VIR_GIGE_DEVICE) {
        const auto& g = devInfo_.SpecialInfo.stGigEInfo;
        info_.vendor = reinterpret_cast<const char*>(g.chManufacturerName);
        info_.modelName = reinterpret_cast<const char*>(g.chModelName);
    } else if (devInfo_.nTLayerType == MV_USB_DEVICE || devInfo_.nTLayerType == MV_VIR_USB_DEVICE) {
        const auto& u = devInfo_.SpecialInfo.stUsb3VInfo;
        info_.vendor = reinterpret_cast<const char*>(u.chManufacturerName);
        info_.modelName = reinterpret_cast<const char*>(u.chModelName);
    }
}

HikCamera::~HikCamera() {
    // 析构兜底：正常流程主窗口已 close，这里是安全网；
    // 析构函数不能抛异常，失败只能吞掉（进程即将退出，无能为力）
    if (!open_)
        return;
    try {
        close();
    } catch (...) {
    }
}

void HikCamera::check(int code, const char* what) const {
    if (code == MV_OK)
        return;
    std::ostringstream oss;
    oss << what << " 失败(0x" << std::hex << code << ")";
    throw CameraError(code, oss.str());
}

// ---------------------------------------------------------------------------
// 生命周期
// ---------------------------------------------------------------------------
void HikCamera::open() {
    if (open_)
        throw CameraError(-1, "设备已打开");
    check(MV_CC_CreateHandle(&handle_, &devInfo_), "CreateHandle");
    try {
        check(MV_CC_OpenDevice(handle_, MV_ACCESS_Exclusive, 0), "OpenDevice");
    } catch (...) {
        MV_CC_DestroyHandle(handle_);  // OpenDevice 失败要销毁句柄，不留半开状态
        handle_ = nullptr;
        throw;
    }
    open_ = true;

    // 强制 Mono8：上层渲染/接口只认 8 位灰度（一帧一字节，简单可靠）。
    // SDK 4.8 没有专门的 SetPixelFormat 接口——像素格式就是枚举节点，走枚举写。
    check(MV_CC_SetEnumValueByString(handle_, "PixelFormat", "Mono8"), "SetPixelFormat(Mono8)");

    // 单帧字节数：取帧缓冲按此分配。查不到就给个安全值（真实值一般在 KB~MB 级）
    MVCC_INTVALUE_EX v{};
    if (MV_CC_GetIntValueEx(handle_, "PayloadSize", &v) == MV_OK)
        payloadSize_ = static_cast<uint64_t>(v.nCurValue);
    else
        payloadSize_ = 1024 * 1024;

    Log::info("海康相机已打开: " + info_.serialNumber);
}

void HikCamera::close() {
    if (!open_)
        throw CameraError(-1, "设备已关闭");
    if (grabbing_)
        MV_CC_StopGrabbing(handle_);
    MV_CC_CloseDevice(handle_);
    MV_CC_DestroyHandle(handle_);
    handle_ = nullptr;
    open_ = false;
    grabbing_ = false;
    Log::info("海康相机已关闭: " + info_.serialNumber);
}

bool HikCamera::isOpen() const {
    return open_;
}

// ---------------------------------------------------------------------------
// 采集控制
// ---------------------------------------------------------------------------
void HikCamera::startGrabbing() {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    check(MV_CC_StartGrabbing(handle_), "StartGrabbing");
    grabbing_ = true;
    Log::info("海康相机开始采集: " + info_.serialNumber);
}

void HikCamera::stopGrabbing() {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    check(MV_CC_StopGrabbing(handle_), "StopGrabbing");
    grabbing_ = false;
    Log::info("海康相机停止采集: " + info_.serialNumber);
}

// grabFrame 的契约（和 VirtualCamera 一致）：
//   - 返回 false：超时无帧（不是错误，调用方稍后再试）
//   - 抛 CameraError：真正的错误（设备未打开等）
bool HikCamera::grabFrame(ImageData& out, uint32_t timeoutMs) {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    if (!grabbing_ || payloadSize_ == 0)
        return false;

    std::vector<unsigned char> buf(static_cast<size_t>(payloadSize_));
    MV_FRAME_OUT_INFO_EX frameInfo{};
    const int rc = MV_CC_GetOneFrameTimeout(handle_, buf.data(),
                                            static_cast<unsigned int>(buf.size()),
                                            &frameInfo, timeoutMs);
    if (rc != MV_OK)
        return false;  // SDK 用错误码表达"超时没有帧"，不是真错误

    out.width = frameInfo.nWidth;
    out.height = frameInfo.nHeight;
    out.format = PixelFormat::Mono8;
    out.frameId = frameInfo.nFrameNum;
    // 设备时间戳单位 ns（SFNC 标准），换算成毫秒；与实际不符时以实测校正
    out.timestamp = ((static_cast<uint64_t>(frameInfo.nDevTimeStampHigh) << 32)
                     | frameInfo.nDevTimeStampLow) / 1000000ull;
    out.data.assign(buf.data(), buf.data() + frameInfo.nFrameLen);
    // GetOneFrameTimeout 的缓冲由 SDK 内部管理，无需配对释放
    // （MV_CC_FreeImageBuffer 只用于 MV_CC_GetImageBuffer 的 MV_FRAME_OUT）
    return true;
}

// ---------------------------------------------------------------------------
// 参数读写：类型路由表决定走哪个 SDK 调用
// ---------------------------------------------------------------------------
void HikCamera::setParam(const std::string& name, int64_t value) {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    // bool 在接口层以 0/1 的 int 承载，靠 JSON 类型表区分
    const auto it = paramTypes_.find(name);
    if (it != paramTypes_.end() && it->second == "bool")
        check(MV_CC_SetBoolValue(handle_, name.c_str(), value != 0), "SetBoolValue");
    else
        check(MV_CC_SetIntValueEx(handle_, name.c_str(), value), "SetIntValueEx");
}

void HikCamera::setParam(const std::string& name, double value) {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    // 相机内部是 32 位浮点，接口的 double 转 float 无精度损失（参数值域远小于 double 精度）
    check(MV_CC_SetFloatValue(handle_, name.c_str(), static_cast<float>(value)), "SetFloatValue");
}

void HikCamera::setParam(const std::string& name, const std::string& value) {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    const auto it = paramTypes_.find(name);
    if (it != paramTypes_.end() && it->second == "enum")
        check(MV_CC_SetEnumValueByString(handle_, name.c_str(), value.c_str()), "SetEnumValueByString");
    else
        check(MV_CC_SetStringValue(handle_, name.c_str(), value.c_str()), "SetStringValue");
}

int64_t HikCamera::getParamInt(const std::string& name) const {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    const auto it = paramTypes_.find(name);
    if (it != paramTypes_.end() && it->second == "bool") {
        bool b = false;
        check(MV_CC_GetBoolValue(handle_, name.c_str(), &b), "GetBoolValue");
        return b ? 1 : 0;
    }
    MVCC_INTVALUE_EX v{};
    check(MV_CC_GetIntValueEx(handle_, name.c_str(), &v), "GetIntValueEx");
    return v.nCurValue;
}

double HikCamera::getParamFloat(const std::string& name) const {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    MVCC_FLOATVALUE v{};
    check(MV_CC_GetFloatValue(handle_, name.c_str(), &v), "GetFloatValue");
    return v.fCurValue;
}

std::string HikCamera::getParamString(const std::string& name) const {
    if (!open_)
        throw CameraError(-1, "设备未打开");
    const auto it = paramTypes_.find(name);
    if (it != paramTypes_.end() && it->second == "enum") {
        // SDK 4.8 读枚举要两步：先取当前值（int），再查值对应的符号名（"Off"/"On"）
        MVCC_ENUMVALUE v{};
        check(MV_CC_GetEnumValue(handle_, name.c_str(), &v), "GetEnumValue");
        MVCC_ENUMENTRY entry{};
        entry.nValue = v.nCurValue;
        check(MV_CC_GetEnumEntrySymbolic(handle_, name.c_str(), &entry), "GetEnumEntrySymbolic");
        return entry.chSymbolic;
    }
    MVCC_STRINGVALUE v{};
    check(MV_CC_GetStringValue(handle_, name.c_str(), &v), "GetStringValue");
    return v.chCurValue;
}

// ---------------------------------------------------------------------------
// 设备信息
// ---------------------------------------------------------------------------
DeviceInfo HikCamera::deviceInfo() const {
    return info_;
}

} // namespace camera

