// 层: 实现层 | 角色: 实现类（海康 MVS SDK 适配）
// impl/hik/hik_camera.h
// 海康相机：CameraInterface 的 MVS SDK 实现（覆盖真实相机和 MVS 内置虚拟相机）。
// MVS 虚拟相机是 MVS 软件里的仿真设备，对 SDK 来说和真实 GigE/USB 相机
// 行为一致：能枚举、能打开、能取流、能读写参数节点，图像由软件生成。
// 参数节点的类型（bool/enum 走不同的 SDK 调用）来自参数描述 JSON——
// 同一个文件既驱动 UI 面板，也充当本类的"写回路由表"。
#pragma once

#include "interface/camera_interface.h"

#include "MvCameraControl.h"

#include <map>
#include <string>

namespace camera {

class HikCamera : public CameraInterface {
public:
    // serial：序列号；devInfo：枚举阶段拿到的设备信息（CreateHandle 要用）；
    // configFile：参数描述 JSON 路径（解析出 key→type 路由表）
    HikCamera(std::string serial, MV_CC_DEVICE_INFO devInfo, std::string configFile);
    ~HikCamera() override;

    // ---- 生命周期 ----
    void open() override;
    void close() override;
    bool isOpen() const override;

    // ---- 采集控制 ----
    void startGrabbing() override;
    void stopGrabbing() override;
    bool grabFrame(ImageData& out, uint32_t timeoutMs = 1000) override;

    // ---- 参数读写 ----
    void setParam(const std::string& name, int64_t value) override;
    void setParam(const std::string& name, double value) override;
    void setParam(const std::string& name, const std::string& value) override;

    int64_t getParamInt(const std::string& name) const override;
    double getParamFloat(const std::string& name) const override;
    std::string getParamString(const std::string& name) const override;

    // ---- 设备信息 ----
    DeviceInfo deviceInfo() const override;

private:
    // SDK 返回非 MV_OK 即抛 CameraError（原始错误码转十六进制，便于查 SDK 文档）
    void check(int code, const char* what) const;

    MV_CC_DEVICE_INFO devInfo_;  // 枚举时拷贝，CreateHandle 用
    void* handle_ = nullptr;     // SDK 设备句柄，open 后非空
    bool open_ = false;
    bool grabbing_ = false;
    uint64_t payloadSize_ = 0;   // 单帧字节数（open 时查 PayloadSize 节点）

    DeviceInfo info_;                            // deviceInfo() 的缓存
    std::map<std::string, std::string> paramTypes_;  // key → "int"/"float"/"enum"/"bool"/"string"
};

} // namespace camera

