// 层: 实现层 | 角色: 实现类（接口的软件模拟替身）
// virtual_camera.cpp
// 虚拟相机实现：所有纯虚函数的具体行为都在这一个文件里。
#include "virtual_camera.h"

#include <iomanip>
#include <sstream>
#include <thread>
#include <utility>

using namespace std::chrono;

namespace camera {

// 静态成员定义：计数器属于"类"而不属于任何实例，所有实例共享它
uint64_t VirtualCamera::serialCounter_ = 0;

VirtualCamera::VirtualCamera(std::string serial)
    : serial_(std::move(serial)) {
    // 默认参数：模拟一台 640x480 单色相机
    intParams_["Width"] = 640;
    intParams_["Height"] = 480;
    intParams_["Gain"] = 0;  // dB
    intParams_["BarEnabled"] = 1;  // 移动竖线开关（bool 参数在虚拟相机里以 int 0/1 存）
    floatParams_["ExposureTime"] = 10000.0;  // 微秒
    stringParams_["TriggerMode"] = "Off";
    stringParams_["DeviceUserID"] = "VirtualCamera-0001";

    // 未显式指定序列号时，自增取号保证唯一（两台默认构造的相机不会撞号）
    if (serial_.empty()) {
        std::ostringstream oss;
        oss << "VSN-" << std::setw(4) << std::setfill('0') << ++serialCounter_;
        serial_ = oss.str();
    }
}

// ---------------------------------------------------------------------------
// 生命周期：状态机严格，非法转换抛 CameraError（而不是静默忽略）
// ---------------------------------------------------------------------------
void VirtualCamera::open() {
    if (state_ != State::Closed)
        throw CameraError(-1, "设备已打开");
    openTime_ = steady_clock::now();
    state_ = State::Open;
}

void VirtualCamera::close() {
    if (state_ == State::Closed)
        throw CameraError(-1, "设备已关闭");
    state_ = State::Closed;
    frameId_ = 0;  // 下次 open 后帧号重新从 1 开始
}

bool VirtualCamera::isOpen() const {
    return state_ != State::Closed;
}

// ---------------------------------------------------------------------------
// 采集控制
// ---------------------------------------------------------------------------
void VirtualCamera::startGrabbing() {
    if (state_ == State::Closed)
        throw CameraError(-1, "设备未打开");
    if (state_ == State::Grabbing)
        throw CameraError(-1, "采集已开始");
    state_ = State::Grabbing;
}

void VirtualCamera::stopGrabbing() {
    if (state_ == State::Closed)
        throw CameraError(-1, "设备未打开");
    state_ = State::Open;  // 回到"已打开未采集"
}

// grabFrame 的契约：
//   - 返回 false：超时无帧（这不是错误，是正常情况，调用方稍后再试）
//   - 抛 CameraError：真正的错误（设备未打开等）
bool VirtualCamera::grabFrame(ImageData& out, uint32_t timeoutMs) {
    if (state_ == State::Closed)
        throw CameraError(-1, "设备未打开");
    if (state_ != State::Grabbing)
        return false;  // 未在采集：模拟"取帧超时"，调用方继续轮询

    // 模拟真实相机的帧间隔（约 30fps）。
    // 真实 SDK 中 timeoutMs 决定最多等多久；这里恒定等待一帧间隔，简化处理。
    (void)timeoutMs;
    std::this_thread::sleep_for(milliseconds(33));

    generateFrame(out);
    return true;
}

// ---------------------------------------------------------------------------
// 参数读写：三个 map 按类型分开存，读取时类型不匹配即报错
// （真实相机的每个参数节点也有固定类型，这里的行为是一致的）
// ---------------------------------------------------------------------------
void VirtualCamera::setParam(const std::string& name, int64_t value) {
    intParams_[name] = value;
}

void VirtualCamera::setParam(const std::string& name, double value) {
    floatParams_[name] = value;
}

void VirtualCamera::setParam(const std::string& name, const std::string& value) {
    stringParams_[name] = value;
}

int64_t VirtualCamera::getParamInt(const std::string& name) const {
    auto it = intParams_.find(name);
    if (it == intParams_.end())
        throw CameraError(-2, "未知参数: " + name);
    return it->second;
}

double VirtualCamera::getParamFloat(const std::string& name) const {
    auto it = floatParams_.find(name);
    if (it == floatParams_.end())
        throw CameraError(-2, "未知参数: " + name);
    return it->second;
}

std::string VirtualCamera::getParamString(const std::string& name) const {
    auto it = stringParams_.find(name);
    if (it == stringParams_.end())
        throw CameraError(-2, "未知参数: " + name);
    return it->second;
}

// ---------------------------------------------------------------------------
// 设备信息
// ---------------------------------------------------------------------------
DeviceInfo VirtualCamera::deviceInfo() const {
    return {"Virtual", "VirtualCamera", serial_};
}

// ---------------------------------------------------------------------------
// 帧生成：水平渐变 + 一条随帧号移动的亮竖线。
// 上层渲染后：渐变证明图像内容正确，移动竖线证明每帧确实在更新（可数帧率）。
// ---------------------------------------------------------------------------
void VirtualCamera::generateFrame(ImageData& out) {
    const uint32_t width = static_cast<uint32_t>(intParams_.at("Width"));
    const uint32_t height = static_cast<uint32_t>(intParams_.at("Height"));

    out.width = width;
    out.height = height;
    out.format = PixelFormat::Mono8;
    out.frameId = ++frameId_;
    out.timestamp = static_cast<uint64_t>(
        duration_cast<milliseconds>(steady_clock::now() - openTime_).count());
    out.data.assign(static_cast<size_t>(width) * height, 0);

    const uint32_t barX = static_cast<uint32_t>(frameId_) % width;
    const bool barEnabled = intParams_.at("BarEnabled") != 0;  // 竖线开关（MVD 面板可勾选）
    for (uint32_t y = 0; y < height; ++y) {
        for (uint32_t x = 0; x < width; ++x) {
            uint8_t v = static_cast<uint8_t>(x * 255 / width);  // 水平渐变
            if (x == barX && barEnabled)
                v = 255;  // 移动亮线
            out.data[static_cast<size_t>(y) * width + x] = v;
        }
    }
}

} // namespace camera

