// 层: 接口层 | 角色: 接口类 + 数据结构（多实现契约）
// camera_interface.h
// 相机抽象接口：定义相机插件契约。
// 本头文件是纯 C++ 接口层，不依赖 Qt / OpenCV / 任何相机 SDK，
// 各品牌相机（海康、虚拟相机等）只需实现本接口即可接入系统。
#pragma once

#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

namespace camera {

// 像素格式（工业相机常见格式，后续按需扩充）
enum class PixelFormat {
    Mono8,      // 8 位灰度
    BayerRG8,   // 8 位 Bayer 彩色
    RGB8,       // 8 位 RGB
    BGR8,       // 8 位 BGR（OpenCV 默认彩色顺序）
    YUV422_8,   // 8 位 YUV422
};

// 图像帧数据：值语义，靠移动传递，不共享底层缓冲
struct ImageData {
    uint32_t width = 0;   // 图像宽（像素）
    uint32_t height = 0;  // 图像高（像素）
    PixelFormat format = PixelFormat::Mono8;
    uint64_t frameId = 0;   // 帧号，单调递增，上层据此检测丢帧
    uint64_t timestamp = 0; // 设备时间戳（毫秒）
    std::vector<uint8_t> data; // 像素数据，长度 = width * height * 每像素字节数
};

// 设备信息：枚举到相机后展示给用户
struct DeviceInfo {
    std::string vendor;       // 厂商
    std::string modelName;    // 型号
    std::string serialNumber; // 序列号
    std::string configFile;   // 参数面板 JSON 路径（工厂枚举时填充；空 = 上层用默认配置）
};

// 相机异常：携带 SDK 原始错误码，同时是 std::runtime_error
class CameraError : public std::runtime_error {
public:
    CameraError(int code, const std::string& msg)
        : std::runtime_error(msg), errorCode_(code) {}

    // 具体实现翻译 SDK 错误码时原样填入，便于上层按错误码分支处理
    int errorCode() const { return errorCode_; }

private:
    int errorCode_;
};

// 相机抽象接口：定义相机插件契约。
// 所有纯虚方法必须由具体相机实现；上层（CameraContext 等）只依赖本接口。
class CameraInterface {
public:
    virtual ~CameraInterface() = default;

    // ---- 生命周期 ----
    virtual void open() = 0;   // 打开设备；失败抛 CameraError
    virtual void close() = 0;  // 关闭设备并释放资源
    virtual bool isOpen() const = 0;

    // ---- 采集控制 ----
    virtual void startGrabbing() = 0;  // 开始采集（相机开始出帧）
    virtual void stopGrabbing() = 0;   // 停止采集

    // 取一帧：阻塞等待，超时返回 false。
    // out 以移动语义填入，调用方无需关心释放。
    virtual bool grabFrame(ImageData& out, uint32_t timeoutMs = 1000) = 0;

    // ---- 参数读写（字符串节点名，海康 MVS 风格）----
    virtual void setParam(const std::string& name, int64_t value) = 0;
    virtual void setParam(const std::string& name, double value) = 0;
    virtual void setParam(const std::string& name, const std::string& value) = 0;

    virtual int64_t getParamInt(const std::string& name) const = 0;
    virtual double getParamFloat(const std::string& name) const = 0;
    virtual std::string getParamString(const std::string& name) const = 0;

    // ---- 设备信息 ----
    virtual DeviceInfo deviceInfo() const = 0;
};

} // namespace camera

