// 层: 观察者 | 角色: 接口类（事件通知契约）
// observer/listener.h
// 监听器接口：想接收系统事件通知的类实现它（如将来的 UI 控件）。
// 观察者模式的核心：事件源只认识本接口，不认识具体监听者——两边解耦。
#pragma once

#include <string>

namespace camera {

class Listener {
public:
    virtual ~Listener() = default;

    // 系统错误通知：采集线程出错等事件广播到这里，UI 可据此显示错误
    virtual void onError(const std::string& message) = 0;
};

} // namespace camera

files.camera/observer/listener_manager.cpp:
// 层: 观察者 | 角色: 管理类（监听者注册/广播）
// observer/listener_manager.cpp
// 观察者管理器实现：注册/注销/广播。
#include "observer/listener_manager.h"

#include "core/log.h"

namespace camera {

void ListenerManager::registerListener(Listener* listener) {
    std::lock_guard<std::mutex> lock(mtx_);
    listeners_.push_back(listener);
}

void ListenerManager::unregisterListener(Listener* listener) {
    std::lock_guard<std::mutex> lock(mtx_);
    // 从列表移除指定监听者（只借指针不拥有，所以只擦除、不 delete）
    for (auto it = listeners_.begin(); it != listeners_.end(); ++it) {
        if (*it == listener) {
            listeners_.erase(it);
            break;  // 一个监听者注册一次，移除一个即可
        }
    }
}

void ListenerManager::notifyError(const std::string& message) const {
    // 全部错误路径在此汇聚：一处落日志（采集线程、UI 转发都走这里）
    Log::error(message);
    // 快照：先拷贝指针列表，再在锁外逐个回调。
    // 若在持锁时调用 onError，监听者内部又注册/注销（同一把锁）→ 死锁
    std::vector<Listener*> snapshot;
    {
        std::lock_guard<std::mutex> lock(mtx_);
        snapshot = listeners_;
    }
    for (Listener* l : snapshot)
        l->onError(message);
}

} // namespace camera

