// 层: 观察者 | 角色: 管理类（监听者注册/广播）
// observer/listener_manager.h
// 观察者管理器：维护监听者列表，负责注册/注销/广播。
// 线程安全：注册可能来自 UI 线程，广播可能来自采集线程，
// 监听者列表用 mutex 保护。广播在锁外进行（回调不应在持锁时执行）。
#pragma once

#include "observer/listener.h"

#include <mutex>
#include <string>
#include <vector>

namespace camera {

class ListenerManager {
public:
    void registerListener(Listener* listener);    // 注册：开始接收通知
    void unregisterListener(Listener* listener);  // 注销：不再接收通知

    // 广播错误事件给所有已注册监听者（快照 + 锁外回调，见实现）
    void notifyError(const std::string& message) const;

private:
    mutable std::mutex mtx_;             // mutable：const 的 notifyError 也要加锁
    std::vector<Listener*> listeners_;   // 借用指针：管理器不拥有监听者生命周期
};

} // namespace camera

