// 层: 进程层 | 角色: 流程类（线程泵：采集循环）
// process/acquire_image_process.cpp
// 采集线程实现：生产循环 + 可停止 + 异常兜底。
#include "process/acquire_image_process.h"

#include <exception>
#include <utility>

namespace camera {

AcquireImageProcess::AcquireImageProcess(CameraContext& ctx, CameraImageQueue& queue,
                                         ListenerManager& listenerMgr)
    : ctx_(ctx), queue_(queue), listenerMgr_(listenerMgr) {}

AcquireImageProcess::~AcquireImageProcess() {
    stop();  // 安全网：析构时保证线程退出，不留下悬空线程
}

void AcquireImageProcess::start() {
    if (thread_.joinable())
        return;  // 已在运行，幂等返回
    // 清掉上一台相机残留的帧：否则消费者会拿到旧相机的画面却以为是新相机的
    queue_.clear();
    running_ = true;
    thread_ = std::thread(&AcquireImageProcess::run, this);
}

void AcquireImageProcess::stop() {
    running_ = false;          // 让生产循环的下一轮检查退出
    if (thread_.joinable())
        thread_.join();        // 阻塞等线程退出，保证 stop 返回后不再有人碰相机
}

void AcquireImageProcess::run() {
    while (running_) {
        ImageData frame;
        try {
            // 500ms 超时：没帧时也能定期醒来检查停止标志
            if (ctx_.grabFrame(frame, 500))
                queue_.push(std::move(frame));
        } catch (const std::exception& e) {
            // 采集出错（如设备被关闭）：广播给监听者（UI 显示错误），然后停泵。
            listenerMgr_.notifyError(e.what());
            running_ = false;
        }
    }
}

} // namespace camera

