// 层: 进程层 | 角色: 流程类（线程泵：采集循环）
// process/acquire_image_process.h
// 图像采集线程（生产者）：循环从 CameraContext 取帧，塞进 CameraImageQueue。
// 职责只负责"泵"——采集的开关（startAcquisition/stopAcquisition）由调用方管，
// 这样泵可以在两台相机间重启，不用重复开启采集。
// 架构图图像流路径的第一段：AcquireImageProcess ->（存图）-> CameraImageQueue。
#pragma once

#include "core/camera_context.h"
#include "observer/listener_manager.h"
#include "process/camera_image_queue.h"

#include <atomic>
#include <thread>

namespace camera {

class AcquireImageProcess {
public:
    AcquireImageProcess(CameraContext& ctx, CameraImageQueue& queue,
                        ListenerManager& listenerMgr);  // 依赖注入
    ~AcquireImageProcess();  // 调用方忘了 stop 也能安全退出（安全网）

    // 线程不可拷贝（拷贝一份线程对象 = 两个线程管一个执行体，崩溃）
    AcquireImageProcess(const AcquireImageProcess&) = delete;
    AcquireImageProcess& operator=(const AcquireImageProcess&) = delete;

    void start();  // 启动采集线程
    void stop();   // 停止采集线程（阻塞直到线程真正退出）

private:
    void run();  // 线程主循环

    CameraContext& ctx_;
    CameraImageQueue& queue_;
    ListenerManager& listenerMgr_;  // 出错时广播给监听者（UI 显示错误）
    std::thread thread_;
    std::atomic<bool> running_ = false;
};

} // namespace camera

