// 层: 进程层 | 角色: 管理类（帧队列：生产者/消费者缓冲）
// process/camera_image_queue.cpp
// 队列实现：锁保护数据，条件变量负责"有帧了/等帧"的唤醒。
#include "process/camera_image_queue.h"

#include <chrono>

namespace camera {

CameraImageQueue::CameraImageQueue(size_t capacity)
    : capacity_(capacity) {}

void CameraImageQueue::push(ImageData frame) {
    {
        std::lock_guard<std::mutex> lock(mtx_);
        // 满则丢最旧：容量=2 即"双缓冲"，消费方永远拿到最新帧
        if (frames_.size() >= capacity_)
            frames_.pop_front();
        frames_.push_back(std::move(frame));  // 移动：整帧像素只换指针，不拷贝
    }
    cv_.notify_one();
}

bool CameraImageQueue::tryPop(ImageData& out, uint32_t timeoutMs) {
    std::unique_lock<std::mutex> lock(mtx_);
    // 等"队列非空"，超时则返回 false（调用方稍后再试）
    if (!cv_.wait_for(lock, std::chrono::milliseconds(timeoutMs),
                      [this] { return !frames_.empty(); }))
        return false;
    out = std::move(frames_.front());  // 移动出去：消费也零拷贝
    frames_.pop_front();
    return true;
}

void CameraImageQueue::clear() {
    std::lock_guard<std::mutex> lock(mtx_);
    frames_.clear();
}

size_t CameraImageQueue::size() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return frames_.size();
}

} // namespace camera

