// 层: 进程层 | 角色: 管理类（帧队列：生产者/消费者缓冲）
// process/camera_image_queue.h
// 线程安全图像队列（生产者-消费者，双缓冲语义）：
//   - 生产者 push：满则丢弃最旧帧，消费方拿到的永远是最新帧（显示不滞后）；
//   - 消费者 tryPop：带超时等待，超时返回 false（这是正常情况，不是错误）。
// 基于 mutex + condition_variable 实现，是架构图"图像处理层"的数据缓冲。
#pragma once

#include "interface/camera_interface.h"

#include <condition_variable>
#include <cstdint>
#include <deque>
#include <mutex>

namespace camera {

class CameraImageQueue {
public:
    // capacity：最多保留几帧。默认 2 即"双缓冲"——满则丢最旧。
    explicit CameraImageQueue(size_t capacity = 2);

    void push(ImageData frame);            // 生产者：存图（移动语义，不拷贝像素）
    bool tryPop(ImageData& out, uint32_t timeoutMs = 1000);  // 消费者：取图
    void clear();                          // 清空队列（切换相机时丢弃旧相机残留帧）
    size_t size() const;                   // 当前排队帧数（调试用）

private:
    // mutable：const 成员函数（如 size()）也要加锁，
    // 但锁本身必须是可修改的——加锁不改变逻辑状态，只保护数据
    mutable std::mutex mtx_;
    std::condition_variable cv_;
    std::deque<ImageData> frames_;
    size_t capacity_;
};

} // namespace camera

