// 层: UI层(agentfw用户层) | 角色: 流程类（AI 对话宿主）
// ui/agent_chat_dialog.cpp
#include "ui/agent_chat_dialog.h"

#include "agentfw/runtime/agent_host.h"
#include "core/camera_context.h"
#include "core/log.h"

#include <QHBoxLayout>
#include <QLineEdit>
#include <QPushButton>
#include <QTextBrowser>
#include <QVBoxLayout>

AgentChatDialog::AgentChatDialog(camera::CameraContext& ctx,
                                 const std::vector<camera::ParamInfo>& params,
                                 const std::string& settingsPath,
                                 const std::string& knowledgePath, QWidget* parent)
    : QDialog(parent),
      ctx_(ctx),
      params_(params),
      settingsPath_(settingsPath),
      knowledgePath_(knowledgePath) {
    setWindowTitle(QStringLiteral("AI 相机助手"));
    resize(560, 480);

    auto* layout = new QVBoxLayout(this);
    log_ = new QTextBrowser(this);
    layout->addWidget(log_);

    auto* inputRow = new QHBoxLayout;
    input_ = new QLineEdit(this);
    input_->setPlaceholderText(QStringLiteral("用自然语言描述，例如：太亮了，调暗一点"));
    sendBtn_ = new QPushButton(QStringLiteral("发送"), this);
    inputRow->addWidget(input_, 1);
    inputRow->addWidget(sendBtn_);
    layout->addLayout(inputRow);

    connect(sendBtn_, &QPushButton::clicked, this, &AgentChatDialog::sendRequest);
    connect(input_, &QLineEdit::returnPressed, this, &AgentChatDialog::sendRequest);

    // 装配框架：失败（配置缺失等）只影响对话功能，不阻断主程序
    try {
        host_ = std::make_unique<camera::agentfw::AgentHost>(ctx_, params_,
                                                             settingsPath_, knowledgePath_);
        appendLine(QStringLiteral("AI 助手已就绪（可多轮对话；支持调参、采集控制、切换相机）"),
                   QStringLiteral("#4a9eff"));
    } catch (const std::exception& e) {
        appendLine(QString("AI 助手初始化失败: ") + e.what(), QStringLiteral("#ff6b6b"));
        input_->setEnabled(false);
        sendBtn_->setEnabled(false);
    }
}

AgentChatDialog::~AgentChatDialog() = default;

void AgentChatDialog::sendRequest() {
    if (!host_ || host_->busy())
        return;
    const QString text = input_->text().trimmed();
    if (text.isEmpty())
        return;
    input_->clear();
    appendLine(QStringLiteral("我：") + text, QStringLiteral("#d8dee9"));
    sendBtn_->setEnabled(false);
    sendBtn_->setText(QStringLiteral("思考中…"));

    host_->startAsync(
        text.toStdString(),
        [this](bool ok, const std::string& result) {
            QMetaObject::invokeMethod(this, [this, ok, r = QString::fromStdString(result)] {
                onDoneFromWorker(ok, r);
            });
        },
        [this](const camera::agentfw::ToolCall& call,
               const camera::agentfw::ToolResult& result) {
            QMetaObject::invokeMethod(this, [this, name = QString::fromStdString(call.name),
                                             r = QString::fromStdString(result.content)] {
                onProgressFromWorker(name, r);
            });
        });
}

void AgentChatDialog::onDoneFromWorker(bool ok, const QString& result) {
    sendBtn_->setEnabled(true);
    sendBtn_->setText(QStringLiteral("发送"));
    if (ok) {
        appendLine(QStringLiteral("AI：") + result, QStringLiteral("#7ee787"));
    } else {
        appendLine(QStringLiteral("AI 请求失败：") + result, QStringLiteral("#ff6b6b"));
    }
}

void AgentChatDialog::onProgressFromWorker(const QString& toolName, const QString& toolResult) {
    appendLine(QStringLiteral("🔧 调用工具 %1 → %2").arg(toolName, toolResult),
               QStringLiteral("#8b949e"));
}

void AgentChatDialog::appendLine(const QString& text, const QString& color) {
    log_->append(QStringLiteral("<span style=\"color:%1\">%2</span>")
                     .arg(color, text.toHtmlEscaped()));
}

