// 层: UI层 | 角色: MVD Delegate（按类型分发编辑器）
// ui/camera_param_delegate.cpp
#include "ui/camera_param_delegate.h"

#include "ui/camera_param_model.h"

#include <QComboBox>
#include <QDoubleSpinBox>
#include <QLineEdit>
#include <QSpinBox>

QWidget* CameraParamDelegate::createEditor(QWidget* parent, const QStyleOptionViewItem&,
                                           const QModelIndex& index) const {
    // 分组行（顶层）或非值列：不提供编辑器 → 视图不可编辑
    if (!index.parent().isValid() || index.column() != CameraParamModel::ColValue)
        return nullptr;

    const QString type = index.data(CameraParamModel::TypeRole).toString();
    const double min = index.data(CameraParamModel::MinRole).toDouble();
    const double max = index.data(CameraParamModel::MaxRole).toDouble();
    const QString unit = index.data(CameraParamModel::UnitRole).toString();

    if (type == "int") {
        auto* sb = new QSpinBox(parent);
        sb->setRange(static_cast<int>(min), static_cast<int>(max));
        if (!unit.isEmpty())
            sb->setSuffix(" " + unit);
        return sb;
    }
    if (type == "float") {
        auto* sb = new QDoubleSpinBox(parent);
        sb->setRange(min, max);
        sb->setDecimals(2);
        if (!unit.isEmpty())
            sb->setSuffix(" " + unit);
        return sb;
    }
    if (type == "enum") {
        auto* cb = new QComboBox(parent);
        cb->addItems(index.data(CameraParamModel::OptionsRole).toStringList());
        return cb;
    }
    if (type == "string")
        return new QLineEdit(parent);
    return nullptr;  // bool：勾选即改，不需要编辑器
}

void CameraParamDelegate::setEditorData(QWidget* editor, const QModelIndex& index) const {
    const QString type = index.data(CameraParamModel::TypeRole).toString();
    const QVariant value = index.data(Qt::EditRole);  // 模型给的原始值
    if (type == "int")
        static_cast<QSpinBox*>(editor)->setValue(static_cast<int>(value.toDouble()));
    else if (type == "float")
        static_cast<QDoubleSpinBox*>(editor)->setValue(value.toDouble());
    else if (type == "enum")
        static_cast<QComboBox*>(editor)->setCurrentText(value.toString());
    else if (type == "string")
        static_cast<QLineEdit*>(editor)->setText(value.toString());
}

void CameraParamDelegate::setModelData(QWidget* editor, QAbstractItemModel* model,
                                       const QModelIndex& index) const {
    const QString type = index.data(CameraParamModel::TypeRole).toString();
    QVariant value;
    if (type == "int")
        value = static_cast<QSpinBox*>(editor)->value();
    else if (type == "float")
        value = static_cast<QDoubleSpinBox*>(editor)->value();
    else if (type == "enum")
        value = static_cast<QComboBox*>(editor)->currentText();
    else if (type == "string")
        value = static_cast<QLineEdit*>(editor)->text();
    else
        return;
    model->setData(index, value, Qt::EditRole);  // 写回由 Model 完成
}

