// ui/camera_param_delegate.h
// MVD 框架的 Delegate：决定"参数值用什么控件编辑"。
//   按模型给出的 TypeRole 分发编辑器：
//     int/float → 数值框（范围来自 MinRole/MaxRole，单位做后缀）
//     enum     → 下拉框（选项来自 OptionsRole）
//     string   → 输入框
//     bool     → 不提供编辑器（模型用 CheckStateRole，视图直接画复选框）
//   分组行 / 名称、范围、单位列 → 返回 nullptr（不可编辑）。
//   Delegate 不认识相机也不认识 JSON，只认模型的角色——这就是"代理"的边界。
#pragma once

#include <QStyledItemDelegate>

class CameraParamDelegate : public QStyledItemDelegate {
public:
