// 层: UI层 | 角色: MVD Model（参数数据+写回相机）
// ui/camera_param_model.cpp
#include "ui/camera_param_model.h"

#include "core/camera_context.h"

#include <QDebug>
#include <QFont>
#include <QStringList>
#include <QVariant>

#include <exception>

namespace {

// 按 JSON 里定义的类型名分发"读哪个 getParam"→ 直接读回 raw 值（字符串）
QString typeName(const camera::ParamInfo& p) { return QString::fromStdString(p.type); }

} // namespace

CameraParamModel::CameraParamModel(camera::CameraContext& ctx, QObject* parent)
    : QAbstractItemModel(parent), ctx_(ctx) {}

// ---- 重建数据：JSON → 分组树（顶层行 = 组，子行 = 参数）----
void CameraParamModel::setParams(std::vector<camera::ParamInfo> params) {
    beginResetModel();
    groups_.clear();
    for (camera::ParamInfo& p : params) {
        // 当前值初始化：数值用 default（int/float 统一存 double），
        // bool/enum/string 各有自己的默认
        QVariant v;
        if (p.type == "bool")
            v = QVariant(p.defaultValue != 0);
        else if (p.type == "enum" || p.type == "string")
            v = QString::fromStdString(p.defaultString);
        else
            v = p.defaultValue;

        // 相邻同组参数归入同一个 GroupRow（JSON 里分组是连续的）
        const QString group = QString::fromStdString(p.group);
        if (groups_.empty() || groups_.back().group != group)
            groups_.push_back({group, {}});
        groups_.back().rows.push_back({std::move(p), v});
    }
    endResetModel();
}

void CameraParamModel::refreshFromCamera() {
    for (int gi = 0; gi < static_cast<int>(groups_.size()); ++gi) {
        GroupRow& g = groups_[gi];
        for (int ri = 0; ri < static_cast<int>(g.rows.size()); ++ri) {
            ParamRow& r = g.rows[ri];
            try {
                if (r.info.type == "int")
                    r.value = static_cast<double>(ctx_.getParamInt(r.info.key));
                else if (r.info.type == "float")
                    r.value = ctx_.getParamFloat(r.info.key);
                else if (r.info.type == "bool")
                    r.value = ctx_.getParamInt(r.info.key) != 0;
                else
                    r.value = QString::fromStdString(ctx_.getParamString(r.info.key));
            } catch (const std::exception&) {
                continue;  // 这台相机没有该参数：保持现状，不报错刷屏
            }
            // 逐行通知视图刷新（行是子行，父索引是分组行）
            const QModelIndex parent = index(gi, 0);
            emit dataChanged(index(ri, ColValue, parent), index(ri, ColValue, parent));
        }
    }
}

// ---- 索引契约：子行索引用 internalId 编码父分组序号（顶层 = 0，子行 = 组号+1）----
QModelIndex CameraParamModel::index(int row, int column, const QModelIndex& parent) const {
    QModelIndex r;
    if (column < 0 || column >= ColCount)
        r = {};
    else if (!parent.isValid()) {  // 顶层行 = 分组
        if (row >= 0 && row < static_cast<int>(groups_.size()))
            r = createIndex(row, column, quintptr(0));
    } else {  // 子行 = 参数，internalId 记住父分组
        const int gi = parent.row();
        if (gi >= 0 && gi < static_cast<int>(groups_.size())
            && row >= 0 && row < static_cast<int>(groups_[gi].rows.size()))
            r = createIndex(row, column, quintptr(gi + 1));
    }
    return r;
}

int CameraParamModel::rowCount(const QModelIndex& parent) const {
    int n = 0;
    if (!parent.isValid())
        n = static_cast<int>(groups_.size());          // 顶层 = 分组数
    else if (!parent.parent().isValid() && parent.row() < static_cast<int>(groups_.size()))
        n = static_cast<int>(groups_[parent.row()].rows.size());  // 组行 → 参数数
    else
        n = 0;                                          // 参数行没有子行
    return n;
}

bool CameraParamModel::hasChildren(const QModelIndex& parent) const {
    return rowCount(parent) > 0;
}

QModelIndex CameraParamModel::sibling(int row, int column, const QModelIndex& idx) const {
    return index(row, column, idx.parent());
}

QModelIndex CameraParamModel::parent(const QModelIndex& child) const {
    if (!child.isValid() || child.internalId() == 0)
        return {};  // 顶层行没有父
    const int gi = static_cast<int>(child.internalId()) - 1;
    if (gi < 0 || gi >= static_cast<int>(groups_.size()))
        return {};
    return createIndex(gi, 0, quintptr(0));
}


int CameraParamModel::columnCount(const QModelIndex&) const {
    return ColCount;
}

QVariant CameraParamModel::data(const QModelIndex& index, int role) const {
    if (!index.isValid())
        return {};
    // 临时插桩：观察绘制/编辑时拿到的索引形态
    static int n = 0;
    if (role == Qt::DisplayRole && n < 30)
        qDebug() << "data r" << index.row() << "c" << index.column() << "parent"
                 << (index.parent().isValid() ? QString("r%1id%2").arg(index.parent().row()).arg(index.parent().internalId()) : "invalid");
    if (role == Qt::DisplayRole) ++n;

    // ---- 分组行（顶层）：只显示组名 ----
    if (!index.parent().isValid()) {
        if (index.row() >= static_cast<int>(groups_.size()))
            return {};
        if (role == Qt::DisplayRole && index.column() == ColName)
            return groups_[index.row()].group;
        if (role == Qt::FontRole) {  // 组名加粗，和参数行区分开
            QFont f;
            f.setBold(true);
            return f;
        }
        return {};
    }

    // ---- 参数行（子行）----
    const GroupRow& g = groups_[index.parent().row()];
    if (index.row() >= static_cast<int>(g.rows.size()))
        return {};
    const ParamRow& r = g.rows[index.row()];

    switch (index.column()) {
    case ColName:
        if (role == Qt::DisplayRole)
            return QString::fromStdString(r.info.name);
        break;
    case ColValue:
        if (role == Qt::CheckStateRole && r.info.type == "bool")
            return r.value.toBool() ? Qt::Checked : Qt::Unchecked;  // bool 画勾选框
        if (role == Qt::DisplayRole)
            return displayValue(r);
        if (role == Qt::EditRole)
            return r.value;  // 编辑器拿原始值（double/字符串），不走格式化
        break;
    case ColRange:
        if (role == Qt::DisplayRole) {
            if (r.info.type == "int" || r.info.type == "float")
                return QString("%1 ~ %2").arg(r.info.min).arg(r.info.max);
            if (r.info.type == "enum") {
                QStringList opts;
                for (const std::string& o : r.info.options)
                    opts << QString::fromStdString(o);
                return opts.join(" / ");
            }
        }
        break;
    case ColUnit:
        if (role == Qt::DisplayRole)
            return QString::fromStdString(r.info.unit);
        break;
    default:
        break;
    }

    // 供 Delegate 用的自定义角色（只在值列被询问，放哪列都安全）
    if (role == TypeRole)
        return typeName(r.info);
    if (role == MinRole)
        return r.info.min;
    if (role == MaxRole)
        return r.info.max;
    if (role == UnitRole)
        return QString::fromStdString(r.info.unit);
    if (role == OptionsRole) {
        QStringList opts;
        for (const std::string& o : r.info.options)
            opts << QString::fromStdString(o);
        return opts;
    }
    return {};
}

// ---- 值列被编辑：写回相机，成功才更新模型 ----
bool CameraParamModel::setData(const QModelIndex& index, const QVariant& value, int role) {
    if (!index.isValid() || !index.parent().isValid() || index.column() != ColValue)
        return false;
    ParamRow& r = groups_[index.parent().row()].rows[index.row()];

    try {
        // 勾选框走 CheckStateRole，编辑器走 EditRole，殊途同归：按类型写回相机
        if (role == Qt::CheckStateRole && r.info.type == "bool") {
            ctx_.setParam(r.info.key, static_cast<int64_t>(value.toInt() == Qt::Checked ? 1 : 0));
            r.value = value.toInt() == Qt::Checked;
        } else if (role == Qt::EditRole) {
            if (r.info.type == "int") {
                const int64_t v = static_cast<int64_t>(value.toDouble());
                ctx_.setParam(r.info.key, v);
                r.value = static_cast<double>(v);
            } else if (r.info.type == "float") {
                ctx_.setParam(r.info.key, value.toDouble());
                r.value = value.toDouble();
            } else {
                ctx_.setParam(r.info.key, value.toString().toStdString());
                r.value = value;
            }
        } else {
            return false;
        }
    } catch (const std::exception& e) {
        // 写失败：模型值不动，返回 false 让视图回滚显示旧值
        emit error(QString("写入失败 [") + QString::fromStdString(r.info.key) + "]: " + e.what());
        return false;
    }
    emit dataChanged(index, index);
    return true;
}

Qt::ItemFlags CameraParamModel::flags(const QModelIndex& index) const {
    Qt::ItemFlags f;
    if (!index.isValid())
        f = Qt::NoItemFlags;
    else {
        const Qt::ItemFlags base = Qt::ItemIsEnabled | Qt::ItemIsSelectable;
        if (!index.parent().isValid())
            f = base;  // 分组行：只读
        else if (index.column() == ColValue) {
            const ParamRow& r = groups_[index.parent().row()].rows[index.row()];
            if (r.info.type == "bool")
                f = base | Qt::ItemIsUserCheckable;  // bool：勾选即改，无需编辑器
            else
                f = base | Qt::ItemIsEditable;
        }
        else
            f = base;  // 名称/范围/单位列：只读
    }
    // 临时插桩
    static int n = 0;
    if (n < 40)
        qDebug() << "flags(" << (index.isValid() ? QString("r%1c%2id%3").arg(index.row()).arg(index.column()).arg(index.internalId()) : "invalid")
                 << ") -> 0x" << Qt::hex << static_cast<int>(f) << (f & Qt::ItemNeverHasChildren ? " NEVER_HAS_CHILDREN!" : "");
    ++n;
    return f;
}

QVariant CameraParamModel::headerData(int section, Qt::Orientation orientation, int role) const {
    if (orientation != Qt::Horizontal || role != Qt::DisplayRole)
        return {};
    switch (section) {
    case ColName:
        return "名称";
    case ColValue:
        return "值";
    case ColRange:
        return "范围";
    case ColUnit:
        return "单位";
    }
    return {};
}

QString CameraParamModel::displayValue(const ParamRow& r) const {
    if (r.info.type == "int")
        return QString::number(r.value.toDouble(), 'f', 0);
    if (r.info.type == "float")
        return QString::number(r.value.toDouble());
    if (r.info.type == "bool")
        return {};  // 勾选框本身表达状态，不再画文字
    return r.value.toString();
}

