// 层: UI层 | 角色: MVD Model（参数数据+写回相机）
// ui/camera_param_model.h
// MVD 框架的 Model：相机参数的树形数据模型（QAbstractItemModel）。
//   顶层行 = 分组（JSON 的 group），子行 = 参数，四列：名称/值/范围/单位。
//   职责：
//     数据端 —— 持有参数描述（ParamInfo）+ 当前值，向视图提供 data()；
//     写回端 —— setData() 按类型调 CameraContext.setParam 写回相机，
//               写失败发 error 信号并返回 false（视图自动回滚显示旧值）。
//   Delegate 不直接认识 ParamInfo，通过 TypeRole/MinRole/MaxRole/
//   OptionsRole/UnitRole 这些自定义角色取编辑所需信息（模型↔代理唯一通道）。
#pragma once

#include "config/param_info.h"

#include <QAbstractItemModel>

#include <vector>

class QVariant;

namespace camera {
class CameraContext;
} // namespace camera

class CameraParamModel : public QAbstractItemModel {
    Q_OBJECT
public:
    enum Column { ColName = 0, ColValue, ColRange, ColUnit, ColCount };

    // 供 Delegate 取"怎么编辑"的角色：类型、数值范围、选项表、单位
    enum Role {
        TypeRole = Qt::UserRole + 1,
        MinRole,
        MaxRole,
        OptionsRole,
        UnitRole,
    };

    explicit CameraParamModel(camera::CameraContext& ctx, QObject* parent = nullptr);

    void setParams(std::vector<camera::ParamInfo> params);  // 重建数据（JSON 热插拔入口）
    void refreshFromCamera();                               // 从相机读回当前值

    // 树模型的索引契约：视图靠 index()/parent()/data() 三个函数导航。
    // 继承 QAbstractItemModel 而非 QAbstractTableModel：后者的平表默认
    // 实现（sibling 丢父级、hasChildren 对非根返回 false）会悄悄破坏树形语义。
    QModelIndex sibling(int row, int column, const QModelIndex& idx) const override;
    bool hasChildren(const QModelIndex& parent) const override;
    QModelIndex index(int row, int column,
                      const QModelIndex& parent = QModelIndex()) const override;
    QModelIndex parent(const QModelIndex& child) const override;

    int rowCount(const QModelIndex& parent) const override;
    int columnCount(const QModelIndex& parent) const override;
    QVariant data(const QModelIndex& index, int role) const override;
    bool setData(const QModelIndex& index, const QVariant& value, int role) override;
    Qt::ItemFlags flags(const QModelIndex& index) const override;
    QVariant headerData(int section, Qt::Orientation orientation,
                        int role) const override;

signals:
    void error(const QString& message);  // 写回相机失败（交给主窗口显示）

private:
    struct ParamRow {               // 一个参数 + 它的当前值
        camera::ParamInfo info;
        QVariant value;
    };
    struct GroupRow {               // 一个分组 + 组内参数
        QString group;
        std::vector<ParamRow> rows;
    };

    QString displayValue(const ParamRow& r) const;  // 按类型格式化值列文本

    camera::CameraContext& ctx_;  // 写回相机（借用引用，不拥有）
    std::vector<GroupRow> groups_;
};

