// 层: UI层 | 角色: UI组件（图像视图：缩放/平移）
// ui/graphics_view.cpp
#include "ui/graphics_view.h"

#include <QGraphicsScene>
#include <QMouseEvent>
#include <QWheelEvent>

#include <cmath>

namespace {
// 缩放范围限制：0.1x ~ 10x，防止滚出天际或缩成针眼
constexpr double kMinScale = 0.1;
constexpr double kMaxScale = 10.0;
} // namespace

GraphicsView::GraphicsView(QWidget* parent)
    : QGraphicsView(parent) {
    // 缩放锚点 = 鼠标位置：滚轮时以光标为中心缩放，而不是视图左上角
    setTransformationAnchor(QGraphicsView::AnchorUnderMouse);
    // 左键拖动 = 平移视图（光标变抓手）
    setDragMode(QGraphicsView::ScrollHandDrag);
}

void GraphicsView::wheelEvent(QWheelEvent* event) {
    // 每格滚轮 = 15° = 120 单位；1.15^步数：上滚放大、下滚缩小，步进柔和
    const double factor = std::pow(1.15, event->angleDelta().y() / 120.0);
    const double newScale = transform().m11() * factor;  // m11 = 当前 x 方向缩放比
    if (newScale < kMinScale || newScale > kMaxScale)
        return;  // 越界：不响应，停在边界
    // 注意：局部变量 newScale 不能叫 scale——会遮蔽 QGraphicsView::scale() 成员函数
    scale(factor, factor);
    event->accept();
}

void GraphicsView::mouseDoubleClickEvent(QMouseEvent* event) {
    fitImage();  // 双击复位全图
    QGraphicsView::mouseDoubleClickEvent(event);
}

void GraphicsView::fitImage() {
    if (scene() && !scene()->items().isEmpty())
        fitInView(scene()->items().first(), Qt::KeepAspectRatio);
}

