namespace {

// 参数配置文件路径：优先取当前设备的 configFile（工厂枚举时填好的），
// 设备没填时退回默认配置。路径锚定 exe 所在目录，不依赖"当前工作目录"
// （相对路径在调试器和双击下解析结果不同；config/ 由 CMake POST_BUILD 拷到 exe 旁）。
QString paramConfigPath(const camera::CameraContext& ctx) {
    const std::string cfg = ctx.deviceInfo().configFile;
    if (!cfg.empty())
        return QString::fromStdString(cfg);
    return QCoreApplication::applicationDirPath() + "/config/virtual_camera.json";
}

} // namespace

MainWindow::MainWindow(camera::CameraContext& ctx, camera::CameraImageQueue& queue,
                       camera::ListenerManager& listenerMgr, ListenerBridge& bridge,
                       std::vector<std::string> serials, QWidget* parent)
    : QMainWindow(parent), ctx_(ctx), queue_(queue), serials_(std::move(serials)) {
    // 界面：由 .ui（Designer 拖出来的）生成，setupUi 把控件装进本窗口
    ui_.reset(new Ui::MainWindow);
    ui_->setupUi(this);

    // 三栏比例：窗口缩放时，多余空间全给中间的图像区（左右栏不抢）。
    // stretch 是"多余空间的分配比例"，0 = 不吃，非 0 = 按比例吃。
    // 想固定 20/60/20 的比例就改成 (1, 3, 1)。
    ui_->mainSplitter->setStretchFactor(0, 0);  // 左栏（控制面板）：宽度固定
    ui_->mainSplitter->setStretchFactor(1, 1);  // 中间（图像区）：独占伸缩
    ui_->mainSplitter->setStretchFactor(2, 0);  // 右栏（参数面板）：宽度固定
    ui_->mainSplitter->setSizes({180, 520, 220});  // 初始宽度（像素）
    // 拖动手柄仍可用（手动微调）；但左右栏不可拖到消失
    ui_->mainSplitter->setCollapsible(0, false);
    ui_->mainSplitter->setCollapsible(2, false);

    // 图像场景：画面黑底，帧来了就更新 pixmapItem_
    scene_ = new QGraphicsScene(this);
    ui_->graphicsView->setScene(scene_);
    pixmapItem_ = scene_->addPixmap(QPixmap());

    // 泵：采集线程，随窗口生灭（关闭窗口自动停，安全网）
    process_ = std::make_unique<camera::AcquireImageProcess>(ctx_, queue_, listenerMgr);

    // 内置标准图标（颜色随深色调色板自动变亮）
    ui_->btnOpen->setIcon(style()->standardIcon(QStyle::SP_DialogOpenButton));
    ui_->btnStart->setIcon(style()->standardIcon(QStyle::SP_MediaPlay));
    ui_->btnSwitch->setIcon(style()->standardIcon(QStyle::SP_BrowserReload));
    ui_->btnStop->setIcon(style()->standardIcon(QStyle::SP_MediaStop));

    // 按钮 → 槽（同一线程内 connect，Direct 直连）
    connect(ui_->btnOpen, &QPushButton::clicked, this, &MainWindow::openCamera);
    connect(ui_->btnStart, &QPushButton::clicked, this, &MainWindow::startAcquisition);
    connect(ui_->btnStop, &QPushButton::clicked, this, &MainWindow::stopAcquisition);
    connect(ui_->btnSwitch, &QPushButton::clicked, this, &MainWindow::switchCamera);

    // 采集线程错误 → 桥接信号 → 主线程槽（跨线程自动排队）
    connect(&bridge, &ListenerBridge::errorOccurred, this, &MainWindow::onError);

    // 取帧定时器：约 30fps，与虚拟相机产帧速度一致
    timer_ = new QTimer(this);
    timer_->setInterval(33);
    connect(timer_, &QTimer::timeout, this, &MainWindow::refreshView);

    // 参数面板：JSON 描述 → 动态控件（热插拔：改 config/virtual_camera.json 不用重编译）
    paramWidget_ = new ParamWidget(ctx_, this);
    ui_->paramBoxLayout->addWidget(paramWidget_);
    try {
        paramWidget_->loadParams(paramConfigPath(ctx_).toStdString());
    } catch (const std::exception& e) {
        statusBar()->showMessage(QString("参数配置加载失败: ") + e.what());
    }
    connect(ui_->btnReload, &QPushButton::clicked, this, [this] {
        try {
            paramWidget_->loadParams(paramConfigPath(ctx_).toStdString());
            statusBar()->showMessage("参数配置已重新加载");
        } catch (const std::exception& e) {
            statusBar()->showMessage(QString("参数配置加载失败: ") + e.what());
        }
    });
    connect(paramWidget_, &ParamWidget::error, this, &MainWindow::onError);

    // AI 助手（agentfw 框架的 Qt 宿主）：打开聊天对话框，框架组件随对话框懒创建
    auto* btnAgent = new QPushButton(QStringLiteral("AI 助手"), ui_->leftPanel);
    ui_->controlLayout->addWidget(btnAgent);
    connect(btnAgent, &QPushButton::clicked, this, [this] {
        try {
            if (!agentDialog_) {
                const auto params =
                    camera::ParseUiJson::parseFile(paramConfigPath(ctx_).toStdString());
                agentDialog_ = std::make_unique<AgentChatDialog>(
                    ctx_, params,
                    QCoreApplication::applicationDirPath().toStdString() + "/config/settings.json",
                    QCoreApplication::applicationDirPath().toStdString() + "/config/knowledge.json");
            }
            agentDialog_->show();
            agentDialog_->raise();
            agentDialog_->activateWindow();
        } catch (const std::exception& e) {
            statusBar()->showMessage(QString("AI 助手启动失败: ") + e.what());
        }
    });

    statusBar()->showMessage("就绪");
    updateCameraInfo();  // 启动即显示当前相机信息（设备信息无需打开相机即可读）
}

MainWindow::~MainWindow() {
    // 关闭窗口时停泵：确保采集线程退出后再销毁，不留悬空线程
    if (process_)
        process_->stop();
}

void MainWindow::openCamera() {
    try {
        ctx_.connectCamera();        // 打开设备
        ctx_.startAcquisition();     // 相机出帧
        process_->start();           // 泵开始转（生产者线程）
        timer_->start();             // 消费者：定时取帧显示
        updateCameraInfo();
        paramWidget_->refreshFromCamera();  // 参数面板读回相机当前值
        statusBar()->showMessage("相机已打开，开始采集");
        camera::Log::info("相机已打开，开始采集: " + ctx_.deviceInfo().serialNumber);
    } catch (const std::exception& e) {
        // 同步错误：直接显示（主线程 catch，安全碰 UI）
        camera::Log::error(std::string("打开失败: ") + e.what());
        statusBar()->showMessage(QString("打开失败: ") + e.what());
    }
}

void MainWindow::startAcquisition() {
    try {
        ctx_.startAcquisition();
        process_->start();
        timer_->start();
        statusBar()->showMessage("开始采集");
        camera::Log::info("开始采集");
    } catch (const std::exception& e) {
        camera::Log::error(std::string("启动失败: ") + e.what());
        statusBar()->showMessage(QString("启动失败: ") + e.what());
    }
}

void MainWindow::stopAcquisition() {
    timer_->stop();
    process_->stop();       // 阻塞等采集线程退出（可安全操作队列/相机）
    ctx_.stopAcquisition();
    statusBar()->showMessage("已停止采集");
    camera::Log::info("已停止采集");
}

void MainWindow::switchCamera() {
    if (serials_.empty())
        return;
    try {
        process_->stop();                     // 先停泵，再动相机
        current_ = (current_ + 1) % serials_.size();
        ctx_.switchCamera(serials_[current_]); // Context 自动停旧机、开新机
        process_->start();
        updateCameraInfo();
        paramWidget_->loadParams(paramConfigPath(ctx_).toStdString());  // 换设备换面板描述
        paramWidget_->refreshFromCamera();
        statusBar()->showMessage(QString("已切换到 ") + QString::fromStdString(serials_[current_]));
        camera::Log::info("切换相机 → " + serials_[current_]);
    } catch (const std::exception& e) {
        camera::Log::error(std::string("切换失败: ") + e.what());
        statusBar()->showMessage(QString("切换失败: ") + e.what());
    }
}

void MainWindow::updateCameraInfo() {
    const camera::DeviceInfo info = ctx_.deviceInfo();
    ui_->lblVendor->setText(QString::fromStdString(info.vendor));
    ui_->lblModel->setText(QString::fromStdString(info.modelName));
    ui_->lblSerial->setText(QString::fromStdString(info.serialNumber));
}

void MainWindow::onError(const QString& message) {
    // 采集线程出错（桥接信号已排队到主线程，这里可安全碰 UI）
    statusBar()->showMessage("错误: " + message);
}

void MainWindow::refreshView() {
    camera::ImageData img;
    // 0ms 超时：没新帧立刻返回，绝不在主线程等待（UI 不能阻塞）
    if (!queue_.tryPop(img, 0))
        return;

    // 虚拟相机是 8 位灰度：1 字节/像素，正好映射 QImage 灰度格式
    QImage qimg(img.data.data(), static_cast<int>(img.width),
                static_cast<int>(img.height), static_cast<int>(img.width),
                QImage::Format_Grayscale8);
    // copy：QImage 不拥有缓冲，img 出函数就销毁，必须拷贝像素
    pixmapItem_->setPixmap(QPixmap::fromImage(qimg.copy()));
    if (!viewInitialized_) {
        // 首帧适配窗口；之后用户自己滚轮缩放/拖动，程序不再插手
        ui_->graphicsView->fitImage();
        viewInitialized_ = true;
    }
}

