// 层: UI层 | 角色: 流程类（主窗口宿主：装配控件与信号）
// ui/main_window.h
// 主窗口（UI 表现层）：图像显示 + 控制按钮。
// 职责边界：按钮只负责"调用 CameraContext"，不碰业务细节；
// 图像由 QTimer 从队列取最新帧显示（主线程，绝不阻塞等帧）。
// 错误两条路：按钮操作同步抛错 → catch 直接显示；
//             采集线程出错 → ListenerBridge 信号 → 状态栏。
#pragma once

#include <QMainWindow>

#include <memory>
#include <string>
#include <vector>

class AgentChatDialog;
class ListenerBridge;
class ParamWidget;
class QGraphicsPixmapItem;
class QGraphicsScene;
class QTimer;

namespace Ui {
class MainWindow;
}

namespace camera {
class AcquireImageProcess;
class CameraContext;
class CameraImageQueue;
class ListenerManager;
} // namespace camera

class MainWindow : public QMainWindow {
    Q_OBJECT
public:
    explicit MainWindow(camera::CameraContext& ctx, camera::CameraImageQueue& queue,
                        camera::ListenerManager& listenerMgr, ListenerBridge& bridge,
                        std::vector<std::string> serials, QWidget* parent = nullptr);
    ~MainWindow();

private slots:
    void openCamera();       // 打开相机 + 开始采集 + 启动泵
    void startAcquisition(); // 恢复采集（若已停止）
    void stopAcquisition();  // 停泵 + 停止采集
    void switchCamera();     // 轮流切换到下一台相机
    void onError(const QString& message);  // 状态栏显示错误（来自桥接信号）
    void refreshView();      // QTimer：取最新帧显示

private:
    void updateCameraInfo(); // 把当前相机信息填进左侧标签
    std::unique_ptr<Ui::MainWindow> ui_;   // Designer 界面（.ui 编译产物）
    QGraphicsScene* scene_ = nullptr;
    QGraphicsPixmapItem* pixmapItem_ = nullptr;
    QTimer* timer_ = nullptr;

    camera::CameraContext& ctx_;
    camera::CameraImageQueue& queue_;
    std::unique_ptr<camera::AcquireImageProcess> process_;  // 泵：随窗口生灭
    ParamWidget* paramWidget_ = nullptr;  // 参数面板（配置驱动，随窗口生灭）

    std::vector<std::string> serials_;  // 所有相机序列号（切换用）
    size_t current_ = 0;                // 当前选中序号
    bool viewInitialized_ = false;      // 首帧已适配过窗口（之后缩放交还用户）

    std::unique_ptr<AgentChatDialog> agentDialog_;  // AI 助手对话框（懒创建，随窗口生灭）
};

