// 层: UI层 | 角色: 流程类（参数面板宿主：MVD 装配）
// ui/param_widget.cpp
#include "ui/param_widget.h"

#include "config/parse_ui_json.h"
#include "ui/camera_param_delegate.h"
#include "ui/camera_param_model.h"

#include <QDebug>
#include <QEvent>
#include <QHeaderView>
#include <QMouseEvent>
#include <QScrollBar>
#include <QTimer>
#include <QTreeView>
#include <QVBoxLayout>

ParamWidget::ParamWidget(camera::CameraContext& ctx, QWidget* parent)
    : QWidget(parent), ctx_(ctx) {
    model_ = new CameraParamModel(ctx_, this);
    delegate_ = new CameraParamDelegate(this);
    tree_ = new QTreeView(this);
    tree_->setModel(model_);
    tree_->setItemDelegate(delegate_);
    tree_->setUniformRowHeights(true);  // 行高统一：大数据量滚动更快
    // 双击或单击选中后编辑（选中即编辑，接近 MVS 的手感）
    tree_->setEditTriggers(QAbstractItemView::DoubleClicked
                           | QAbstractItemView::SelectedClicked);

    // 列宽策略：名称/范围/单位按内容自适应，值列吃满剩余宽度（编辑器需要空间）
    QHeaderView* header = tree_->header();
    header->setStretchLastSection(false);
    header->setSectionResizeMode(CameraParamModel::ColName, QHeaderView::ResizeToContents);
    header->setSectionResizeMode(CameraParamModel::ColValue, QHeaderView::Stretch);
    header->setSectionResizeMode(CameraParamModel::ColRange, QHeaderView::ResizeToContents);
    header->setSectionResizeMode(CameraParamModel::ColUnit, QHeaderView::ResizeToContents);

    auto* root = new QVBoxLayout(this);
    root->setContentsMargins(0, 0, 0, 0);
    root->addWidget(tree_);

    // 模型写回相机失败 → 转发给主窗口（状态栏显示）
    connect(model_, &CameraParamModel::error, this, &ParamWidget::error);

    // 临时诊断：挂在视口上，记录每次真实点击 → indexAt 的命中结果
    tree_->viewport()->installEventFilter(this);
}

// 临时诊断：点击证据。pos 是视口坐标，与 indexAt 的输入坐标系一致。
// 三个数字对应 indexAt 源码里的三个环节：
//   hit 行 ← itemAtCoordinate(y) = (y + vbar->value()) / defaultItemHeight
//   hit 列 ← columnAt(x)     = header->logicalIndexAt(x)
//   hit 有效性 ← sibling(row, column) 走模型的 index()
bool ParamWidget::eventFilter(QObject* obj, QEvent* event) {
    if (obj == tree_->viewport()
        && (event->type() == QEvent::MouseButtonPress
            || event->type() == QEvent::MouseButtonDblClick)) {
        const auto* me = static_cast<QMouseEvent*>(event);
        const QPoint p = me->position().toPoint();
        const QModelIndex hit = tree_->indexAt(p);
        qDebug() << "CLICK" << (event->type() == QEvent::MouseButtonDblClick ? "双击" : "单击")
                 << "pos=" << p
                 << "headerCol=" << tree_->header()->logicalIndexAt(p.x())
                 << "vbar=" << tree_->verticalScrollBar()->value()
                 << "hit r=" << (hit.isValid() ? hit.row() : -1)
                 << "parent=" << (hit.isValid() && hit.parent().isValid() ? hit.parent().row() : -1)
                 << "col=" << (hit.isValid() ? hit.column() : -1);
    }
    return QObject::eventFilter(obj, event);
}

void ParamWidget::loadParams(const std::string& jsonPath) {
    // 解析失败抛 CameraError（不吞，由主窗口 catch 显示）；成功则重建模型
    model_->setParams(camera::ParseUiJson::parseFile(jsonPath));

    // 行项（内部 QTreeViewItem）不是 setModel 时立刻建的：Qt 把首次构建
    // 延迟到窗口显示之后（内部 0ms 定时器）。赶在它前面调 expandAll 只会
    // 落空——行项还不存在，展开标记无处可挂；之后行项按"收起"建出来，
    // 子行永远不会补建，分组就成了"假叶子"（没箭头、打不开、参数不显示）。
    // 这是"两次运行结果不同"的根因：0ms 定时器谁先跑是竞态。
    // 方案：稍长的延迟确保跑在 Qt 内部构建之后；先展开（标记挂在真实行项
    // 上），再强制重排（展开状态驱动子行补建）。
    QTimer::singleShot(50, this, [this] {
        tree_->expandAll();  // 行项已建好：展开标记生效，展开本身会触发重排
    });

    // 临时诊断：T+3s 输出几何证据——每行 visualRect 与 indexAt(行中心) 的对照。
    // 若 visualRect 正常（行高≈15、逐行递增）而 indexAt 命中错行 → 命中测试状态坏了；
    // 若 indexAt 全对 → 说明视图自身一致，问题在点击坐标映射或选择路径。
    QTimer::singleShot(3000, this, [this] {
        QStringList lines;
        for (int gi = 0; gi < model_->rowCount(QModelIndex()); ++gi) {
            const QModelIndex g = model_->index(gi, 0);
            const QRect gr = tree_->visualRect(g);
            const QModelIndex gh = tree_->indexAt(gr.center());
            lines << QString("组%1 y=%2 h=%3 hit=r%4")
                         .arg(gi).arg(gr.y()).arg(gr.height())
                         .arg(gh.isValid() ? gh.row() : -1);
            for (int ri = 0; ri < model_->rowCount(g); ++ri) {
                const QModelIndex c = model_->index(ri, CameraParamModel::ColValue, g);
                const QRect cr = tree_->visualRect(c);
                const QModelIndex ch = tree_->indexAt(cr.center());
                lines << QString("参%1.%2 x=%3 w=%4 y=%5 h=%6 hit=r%7(%8)")
                             .arg(gi).arg(ri)
                             .arg(cr.x()).arg(cr.width()).arg(cr.y()).arg(cr.height())
                             .arg(ch.isValid() ? ch.row() : -1)
                             .arg(ch.isValid() && ch.parent().isValid() ? ch.parent().row() : -1);
            }
        }
        qDebug() << "T3s几何:" << lines.join(" | ");
        QStringList hdr;
        for (int c = 0; c < CameraParamModel::ColCount; ++c)
            hdr << QString("列%1 pos=%2 size=%3").arg(c)
                       .arg(tree_->header()->sectionViewportPosition(c))
                       .arg(tree_->header()->sectionSize(c));
        qDebug() << "T3s表头:" << hdr.join(" | ")
                 << "vbar=" << tree_->verticalScrollBar()->value()
                 << "视口高=" << tree_->viewport()->height()
                 << "视口原点(屏幕)=" << tree_->viewport()->mapToGlobal(QPoint(0, 0));
    });
}

void ParamWidget::refreshFromCamera() {
    model_->refreshFromCamera();
}

