// 层: UI层 | 角色: 流程类（参数面板宿主：MVD 装配）
// ui/param_widget.h
// 参数面板（架构"UI 表现层"的 ParamWidget）：MVD 框架的 View 宿主。
//   三层各司其职：
//     Model    —— CameraParamModel：参数数据 + 写回相机
//     View     —— QTreeView：显示分组树，分组行 + 参数行
//     Delegate —— CameraParamDelegate：按类型分发编辑器
//   对外接口与旧版一致（loadParams / refreshFromCamera / error），主窗口零改动。
#pragma once

#include <QWidget>

#include <string>

class CameraParamDelegate;
class CameraParamModel;
class QEvent;
class QTreeView;

namespace camera {
class CameraContext;
} // namespace camera

class ParamWidget : public QWidget {
    Q_OBJECT
public:
    explicit ParamWidget(camera::CameraContext& ctx, QWidget* parent = nullptr);

    void loadParams(const std::string& jsonPath);  // 解析 JSON → 模型重建（热插拔入口）
    void refreshFromCamera();                      // 从相机读回当前值刷新模型

    // 临时诊断：记录每次真实点击的坐标与 indexAt 命中结果
    bool eventFilter(QObject* obj, QEvent* event) override;

signals:
    void error(const QString& message);  // 读写参数失败（交给主窗口显示）

private:
    camera::CameraContext& ctx_;
    CameraParamModel* model_ = nullptr;      // MVD 的 Model
    CameraParamDelegate* delegate_ = nullptr;  // MVD 的 Delegate
    QTreeView* tree_ = nullptr;              // MVD 的 View
};
